    #[test]
    fn chartex_axis_tick_marks_require_an_authored_type() {
        let xml = r#"<cx:chartSpace xmlns:cx="http://schemas.microsoft.com/office/drawing/2014/chartex">
            <cx:axis id="0"><cx:catScaling/><cx:majorTickMarks type="out"/></cx:axis>
            <cx:axis id="1"><cx:valScaling/></cx:axis>
        </cx:chartSpace>"#;
        let d = root_of(xml);
        let cat_axis = d
            .root_element()
            .descendants()
            .find(|node| node.is_element() && child(*node, "catScaling").is_some());
        let val_axis = d
            .root_element()
            .descendants()
            .find(|node| node.is_element() && child(*node, "valScaling").is_some());
        assert_eq!(
            extract_chartex_axis_tick_mark(cat_axis, "majorTickMarks"),
            "out"
        );
        assert_eq!(
            extract_chartex_axis_tick_mark(val_axis, "majorTickMarks"),
            "none"
        );
    }

    #[test]
    fn classic_tick_mark_distinguishes_bare_element_from_omission() {
        let xml =
            format!(r#"<c:valAx xmlns:c="{C_NS}"><c:majorTickMark/><c:minorTickMark/></c:valAx>"#,);
        let document = root_of(&xml);
        let axis = document.root_element();
        assert_eq!(
            extract_axis_tick_mark_or_default(axis, "majorTickMark"),
            "cross"
        );
        assert_eq!(
            extract_axis_tick_mark(axis, "minorTickMark").as_deref(),
            Some("cross")
        );

        let omitted_xml = format!(r#"<c:valAx xmlns:c="{C_NS}"/>"#);
        let omitted = root_of(&omitted_xml);
        let axis = omitted.root_element();
        assert_eq!(
            extract_axis_tick_mark_or_default(axis, "majorTickMark"),
            "out"
        );
        assert_eq!(extract_axis_tick_mark(axis, "minorTickMark"), None);
    }

    #[test]
    fn chart_title_text_size_bold_srgb() {
        let xml = r#"<c:chart xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">
            <c:title><c:tx><c:rich>
                <a:p><a:pPr><a:defRPr sz="1400" b="1"><a:solidFill><a:srgbClr val="1B4332"/></a:solidFill></a:defRPr></a:pPr>
                <a:r><a:t>Carbon &amp; Growth</a:t></a:r></a:p>
            </c:rich></c:tx></c:title>
        </c:chart>"#;
        let d = root_of(xml);
        let root = d.root_element();
        assert_eq!(
            extract_chart_title_text(root).as_deref(),
            Some("Carbon & Growth")
        );
        assert_eq!(extract_chart_title_size(root), Some(1400));
        assert_eq!(extract_chart_title_bold(root), Some(true));
        assert_eq!(extract_chart_title_srgb(root).as_deref(), Some("1B4332"));
    }

    #[test]
    fn chart_title_rich_runs_preserve_newline_and_independent_typography() {
        let xml = format!(
            r#"<c:title xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:tx><c:rich>
              <a:p><a:r><a:rPr sz="1800" b="1"/><a:t>Long heading</a:t></a:r>
                <a:r><a:rPr sz="1400" i="1"><a:solidFill><a:srgbClr val="112233"/></a:solidFill></a:rPr><a:t>
Subtitle</a:t></a:r></a:p>
            </c:rich></c:tx></c:title>"#
        );
        let document = root_of(&xml);
        let runs = parse_chart_title_rich_runs(document.root_element(), &StubResolver)
            .expect("rich title runs");
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0].text, "Long heading");
        assert_eq!(runs[0].font_size_hpt, Some(1800));
        assert_eq!(runs[0].bold, Some(true));
        assert_eq!(runs[1].text, "\nSubtitle");
        assert_eq!(runs[1].font_size_hpt, Some(1400));
        assert_eq!(runs[1].italic, Some(true));
        assert_eq!(runs[1].color.as_deref(), Some("112233"));
    }

    #[test]
    fn chart_text_font_sizes_enforce_st_text_font_size_boundaries() {
        for (size, expected) in [
            ("99", None),
            ("100", Some(100)),
            ("400000", Some(400_000)),
            ("400001", None),
        ] {
            let xml = format!(
                r#"<c:chart xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:title><c:tx><c:rich><a:p><a:r><a:rPr sz="{size}"/><a:t>T</a:t></a:r></a:p></c:rich></c:tx></c:title>
                  <c:txPr><a:p><a:pPr><a:defRPr sz="{size}"/></a:pPr></a:p></c:txPr>
                  <c:legend><c:txPr><a:p><a:pPr><a:defRPr sz="{size}"/></a:pPr></a:p></c:txPr></c:legend>
                </c:chart>"#
            );
            let document = root_of(&xml);
            let root = document.root_element();
            assert_eq!(extract_chart_title_size(root), expected, "title {size}");
            assert_eq!(extract_axis_tick_label_size(root), expected, "axis {size}");
            assert_eq!(extract_legend_text_props(root).1, expected, "legend {size}");
        }
    }

