    // ── Axis scale model (CH6) ──────────────────────────────────────────────

    #[test]
    fn axis_gridlines_presence() {
        // Value axis with `<c:majorGridlines>` → true; category axis without → false.
        let val = format!(r#"<c:valAx xmlns:c="{C_NS}"><c:majorGridlines/></c:valAx>"#);
        assert!(axis_has_major_gridlines(root_of(&val).root_element()));
        assert!(!axis_has_minor_gridlines(root_of(&val).root_element()));

        let cat = format!(r#"<c:catAx xmlns:c="{C_NS}"/>"#);
        assert!(!axis_has_major_gridlines(root_of(&cat).root_element()));

        let both = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:majorGridlines/><c:minorGridlines/></c:valAx>"#
        );
        assert!(axis_has_major_gridlines(root_of(&both).root_element()));
        assert!(axis_has_minor_gridlines(root_of(&both).root_element()));
    }

    #[test]
    fn minor_gridline_no_fill_suppresses_the_effective_stroke() {
        let visible = format!(
            r#"<c:valAx xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:minorGridlines><c:spPr><a:ln><a:solidFill><a:srgbClr val="112233"/></a:solidFill></a:ln></c:spPr></c:minorGridlines></c:valAx>"#
        );
        let hidden = format!(
            r#"<c:valAx xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:minorGridlines><c:spPr><a:ln><a:noFill/></a:ln></c:spPr></c:minorGridlines></c:valAx>"#
        );
        assert!(axis_minor_gridlines_visible(
            root_of(&visible).root_element()
        ));
        assert!(!axis_minor_gridlines_visible(
            root_of(&hidden).root_element()
        ));
        // Presence remains independently queryable for callers that need the
        // authored request rather than its effective paint visibility.
        assert!(axis_has_minor_gridlines(root_of(&hidden).root_element()));
    }

    #[test]
    fn axis_major_minor_unit() {
        let xml = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:crossBetween val="between"/><c:majorUnit val="500"/><c:minorUnit val="100"/></c:valAx>"#
        );
        assert_eq!(
            extract_axis_major_unit(root_of(&xml).root_element()),
            Some(500.0)
        );
        assert_eq!(
            extract_axis_minor_unit(root_of(&xml).root_element()),
            Some(100.0)
        );
        // Absent → None (auto step).
        let bare = format!(r#"<c:valAx xmlns:c="{C_NS}"/>"#);
        assert_eq!(extract_axis_major_unit(root_of(&bare).root_element()), None);
        // Non-positive rejected (would wedge the gridline loop).
        let zero = format!(r#"<c:valAx xmlns:c="{C_NS}"><c:majorUnit val="0"/></c:valAx>"#);
        assert_eq!(extract_axis_major_unit(root_of(&zero).root_element()), None);
    }

    #[test]
    fn axis_log_base() {
        let xml = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:scaling><c:logBase val="10"/></c:scaling></c:valAx>"#
        );
        assert_eq!(
            extract_axis_log_base(root_of(&xml).root_element()),
            Some(10.0)
        );
        // Base < 2 is invalid per ST_LogBase → rejected.
        let bad = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:scaling><c:logBase val="1"/></c:scaling></c:valAx>"#
        );
        assert_eq!(extract_axis_log_base(root_of(&bad).root_element()), None);
        // Absent scaling / logBase → None (linear).
        let bare = format!(r#"<c:valAx xmlns:c="{C_NS}"><c:scaling/></c:valAx>"#);
        assert_eq!(extract_axis_log_base(root_of(&bare).root_element()), None);
    }

    #[test]
    fn axis_orientation() {
        let rev = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:scaling><c:orientation val="maxMin"/></c:scaling></c:valAx>"#
        );
        assert_eq!(
            extract_axis_orientation(root_of(&rev).root_element()).as_deref(),
            Some("maxMin")
        );
        let norm = format!(
            r#"<c:valAx xmlns:c="{C_NS}"><c:scaling><c:orientation val="minMax"/></c:scaling></c:valAx>"#
        );
        assert_eq!(
            extract_axis_orientation(root_of(&norm).root_element()).as_deref(),
            Some("minMax")
        );
        // Absent → None (renderer treats as minMax).
        let bare = format!(r#"<c:valAx xmlns:c="{C_NS}"><c:scaling/></c:valAx>"#);
        assert_eq!(
            extract_axis_orientation(root_of(&bare).root_element()),
            None
        );
    }

    #[test]
    fn axis_tick_label_pos_and_rotation() {
        let xml = format!(
            r#"<c:catAx xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:tickLblPos val="low"/><c:txPr><a:bodyPr rot="-2700000"/></c:txPr></c:catAx>"#
        );
        assert_eq!(
            extract_axis_tick_label_pos(root_of(&xml).root_element()).as_deref(),
            Some("low")
        );
        assert_eq!(
            extract_axis_tick_label_rotation(root_of(&xml).root_element()),
            Some(-2_700_000)
        );
        // Absent → None (renderer treats as nextTo / 0°).
        let bare = format!(r#"<c:catAx xmlns:c="{C_NS}"/>"#);
        assert_eq!(
            extract_axis_tick_label_pos(root_of(&bare).root_element()),
            None
        );
        assert_eq!(
            extract_axis_tick_label_rotation(root_of(&bare).root_element()),
            None
        );
    }

    #[test]
    fn series_trendlines_parse() {
        // No trendline → None (byte-stable).
        let none = format!(r#"<c:ser xmlns:c="{C_NS}"/>"#);
        assert_eq!(
            extract_series_trendlines(root_of(&none).root_element(), &StubResolver),
            None
        );
        // A linear fit + a period-3 moving average, the linear one with a red line.
        let xml = format!(
            r#"<c:ser xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                 <c:trendline>
                   <c:name>Authored trend name</c:name>
                   <c:spPr><a:ln w="19050"><a:solidFill><a:srgbClr val="ff0000"/></a:solidFill><a:prstDash val="dash"/></a:ln></c:spPr>
                   <c:trendlineType val="linear"/>
                   <c:dispEq val="1"/>
                   <c:dispRSqr val="1"/>
                   <c:trendlineLbl>
                     <c:numFmt formatCode="0.00" sourceLinked="0"/>
                     <c:layout><c:manualLayout><c:xMode val="edge"/><c:yMode val="edge"/><c:x val="0.1"/><c:y val="0.2"/></c:manualLayout></c:layout>
                     <c:tx><c:rich><a:bodyPr rot="1800000" wrap="none" anchor="b" lIns="12700"/><a:p><a:pPr algn="r"><a:defRPr sz="1800" b="1"><a:solidFill><a:srgbClr val="123456"/></a:solidFill><a:latin typeface="Georgia"/></a:defRPr></a:pPr><a:r><a:rPr sz="2000" b="0" i="1" lang="en-US" baseline="25000"><a:solidFill><a:srgbClr val="654321"/></a:solidFill></a:rPr><a:t>Authored</a:t></a:r></a:p><a:p><a:r><a:t>fit</a:t></a:r></a:p></c:rich></c:tx>
                     <c:spPr><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill><a:ln w="25400"><a:solidFill><a:srgbClr val="808080"/></a:solidFill></a:ln></c:spPr>
                     <c:txPr><a:bodyPr/><a:p><a:pPr algn="ctr"><a:defRPr sz="1800" b="1"><a:solidFill><a:srgbClr val="123456"/></a:solidFill><a:latin typeface="Georgia"/></a:defRPr></a:pPr></a:p></c:txPr>
                   </c:trendlineLbl>
                 </c:trendline>
                 <c:trendline>
                   <c:spPr><a:ln><a:noFill/></a:ln></c:spPr>
                   <c:trendlineType val="movingAvg"/>
                   <c:period val="3"/>
                 </c:trendline>
                 <c:trendline>
                   <c:trendlineType val="linear"/>
                   <c:trendlineLbl><c:tx><c:strRef><c:strCache><c:ptCount val="1"/><c:pt idx="0"><c:v>Cached fit</c:v></c:pt></c:strCache></c:strRef></c:tx></c:trendlineLbl>
                 </c:trendline>
               </c:ser>"#
        );
        let got = extract_series_trendlines(root_of(&xml).root_element(), &StubResolver).unwrap();
        assert_eq!(got.len(), 3);
        assert_eq!(got[0].name.as_deref(), Some("Authored trend name"));
        assert_eq!(got[0].trendline_type, "linear");
        assert_eq!(got[0].line_color.as_deref(), Some("FF0000"));
        assert_eq!(got[0].line_width_emu, Some(19050));
        assert_eq!(got[0].line_dash.as_deref(), Some("dash"));
        assert_eq!(got[0].disp_eq, Some(true));
        assert_eq!(got[0].disp_r_sqr, Some(true));
        assert_eq!(got[0].label_text.as_deref(), Some("Authored\nfit"));
        let rich_runs = got[0]
            .label_rich_runs
            .as_ref()
            .expect("trendline rich runs");
        assert_eq!(
            rich_runs
                .iter()
                .map(|run| run.text.as_str())
                .collect::<String>(),
            "Authored\nfit"
        );
        assert_eq!(rich_runs[0].paragraph_align.as_deref(), Some("r"));
        assert_eq!(rich_runs[0].italic, Some(true));
        assert_eq!(rich_runs[2].paragraph_align, None);
        assert_eq!(got[0].label_format_code.as_deref(), Some("0.00"));
        assert_eq!(got[0].label_format_source_linked, Some(false));
        assert_eq!(got[0].label_font_size_hpt, Some(1800));
        assert_eq!(got[0].label_font_bold, Some(true));
        assert_eq!(got[0].label_font_italic, None);
        assert_eq!(got[0].label_font_color.as_deref(), Some("123456"));
        assert_eq!(got[0].label_font_face.as_deref(), Some("Georgia"));
        assert_eq!(got[0].label_font_language, None);
        assert_eq!(got[0].label_font_baseline, None);
        assert_eq!(got[0].label_text_rotation, Some(1_800_000));
        assert_eq!(got[0].label_text_wrap.as_deref(), Some("none"));
        assert_eq!(got[0].label_text_vertical_anchor.as_deref(), Some("b"));
        assert_eq!(got[0].label_text_l_ins_emu, Some(12_700));
        assert_eq!(got[0].label_text_align.as_deref(), Some("ctr"));
        let label_box = got[0].label_box.as_ref().expect("trendline label box");
        assert_eq!(label_box.fill.as_deref(), Some("FFFFFF"));
        assert_eq!(label_box.border_color.as_deref(), Some("808080"));
        assert_eq!(label_box.border_width_emu, Some(25400));
        let manual = got[0]
            .label_manual_layout
            .as_ref()
            .expect("trendline label manual layout");
        assert_eq!(manual.x_mode, "edge");
        assert_eq!(manual.y_mode, "edge");
        assert_eq!(manual.x, 0.1);
        assert_eq!(manual.y, 0.2);
        assert_eq!(got[1].trendline_type, "movingAvg");
        assert_eq!(got[1].period, Some(3));
        assert_eq!(got[1].line_color, None);
        assert_eq!(got[0].line_hidden, None);
        assert_eq!(got[1].line_hidden, Some(true));
        assert_eq!(got[2].label_text.as_deref(), Some("Cached fit"));
    }

    #[test]
    fn trendline_rich_run_paint_does_not_become_the_label_default() {
        let xml = format!(
            r#"<c:ser xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:trendline>
              <c:trendlineType val="linear"/><c:trendlineLbl><c:tx><c:rich>
                <a:p><a:pPr><a:defRPr><a:noFill/></a:defRPr></a:pPr><a:r><a:t>A</a:t></a:r></a:p>
                <a:p><a:r><a:t>B</a:t></a:r></a:p>
              </c:rich></c:tx></c:trendlineLbl>
            </c:trendline></c:ser>"#
        );
        let trendline = extract_series_trendlines(root_of(&xml).root_element(), &StubResolver)
            .unwrap()
            .remove(0);
        assert_eq!(trendline.label_font_color, None);
        assert_eq!(trendline.label_font_paint_authored, None);
        assert_eq!(trendline.label_font_hidden, None);
        let runs = trendline.label_rich_runs.expect("rich runs");
        assert_eq!(runs[0].color_paint_authored, Some(true));
        assert_eq!(runs[0].color_hidden, Some(true));
        assert_eq!(runs[1].text, "\n");
        assert_eq!(runs[2].color_paint_authored, None);
        assert_eq!(runs[2].color_hidden, None);
    }

    // ========================================================================
    // `parse_chart_part` direct contract tests.
    //
    // These call the shared entry point itself (not the per-crate wrappers),
    // so a future edit that breaks the parse — in this PR or in PR2 (xlsx
    // switch) / PR3 (chartEx) — fails here first. Each test asserts concrete
    // output values (chart-type strings, hex colors, font names, axis
    // presence/absence) rather than just "parses without panicking", so the
    // parse *contract* is pinned, not merely its shape.

    /// Minimal theme-aware resolver for `parse_chart_part` tests: resolves
    /// `<a:srgbClr>` verbatim (uppercased, matching real resolvers' hex
    /// normalization) and `<a:schemeClr>` against a small fixed table covering
    /// the slots real decks use for chart text/borders. Also overrides the
    /// theme major/minor Latin font hooks so CH10 theme-fallback fields can be
    /// exercised without pulling in a crate's full theme parser.
    struct FixtureResolver;

    impl ColorResolver for FixtureResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            let c = node.children().find(|n| {
                n.is_element() && matches!(n.tag_name().name(), "srgbClr" | "schemeClr")
            })?;
            match c.tag_name().name() {
                "srgbClr" => c.attribute("val").map(|v| v.to_uppercase()),
                "schemeClr" => match c.attribute("val")? {
                    "accent1" => Some("4472C4".to_string()),
                    "accent2" => Some("ED7D31".to_string()),
                    "accent3" => Some("A5A5A5".to_string()),
                    "tx1" | "dk1" => Some("000000".to_string()),
                    "bg1" | "lt1" => Some("FFFFFF".to_string()),
                    _ => None,
                },
                _ => None,
            }
        }

        fn resolve_scheme_color(&self, name: &str) -> Option<String> {
            match name {
                "accent1" => Some("4472C4".to_string()),
                "accent2" => Some("ED7D31".to_string()),
                "accent3" => Some("A5A5A5".to_string()),
                "tx1" | "dk1" => Some("000000".to_string()),
                "bg1" | "lt1" => Some("FFFFFF".to_string()),
                _ => None,
            }
        }

        fn theme_major_font_latin(&self) -> Option<String> {
            Some("Calibri Light".to_string())
        }

        fn theme_minor_font_latin(&self) -> Option<String> {
            Some("Calibri".to_string())
        }

        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            // Cycle a 6-accent palette exactly like the docx resolver so chartEx
            // box/sunburst tests can assert the branch/series colors.
            const ACCENTS: [&str; 6] = ["5B9BD5", "ED7D31", "A5A5A5", "FFC000", "4472C4", "70AD47"];
            Some(ACCENTS[idx % 6].to_string())
        }
    }

    struct XlsxCompatibilityFixtureResolver;

    impl ColorResolver for XlsxCompatibilityFixtureResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            FixtureResolver.resolve_solid_fill(node)
        }

        fn resolve_scheme_color(&self, name: &str) -> Option<String> {
            FixtureResolver.resolve_scheme_color(name)
        }

        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            FixtureResolver.resolve_series_accent(idx)
        }

        fn implicit_outline_only_negative_column_style(&self) -> bool {
            true
        }
    }

    struct DarkRedFixtureResolver;

    impl ColorResolver for DarkRedFixtureResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            FixtureResolver.resolve_solid_fill(node)
        }

        fn resolve_scheme_color(&self, name: &str) -> Option<String> {
            match name {
                "tx1" | "dk1" => Some("240000".to_string()),
                _ => FixtureResolver.resolve_scheme_color(name),
            }
        }

        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            FixtureResolver.resolve_series_accent(idx)
        }
    }

    struct WhiteChartFixtureResolver;

    impl ColorResolver for WhiteChartFixtureResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            FixtureResolver.resolve_solid_fill(node)
        }

        fn resolve_scheme_color(&self, name: &str) -> Option<String> {
            FixtureResolver.resolve_scheme_color(name)
        }

        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            FixtureResolver.resolve_series_accent(idx)
        }

        fn default_chart_bg(&self) -> Option<String> {
            Some("FFFFFF".to_string())
        }

        fn default_plot_area_bg(&self) -> Option<String> {
            Some("FFFFFF".to_string())
        }
    }

    struct FormatSchemeFixtureResolver {
        format_scheme: crate::theme::ThemeFormatScheme,
    }

    impl ColorResolver for FormatSchemeFixtureResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            FixtureResolver.resolve_solid_fill(node)
        }

        fn resolve_scheme_color(&self, name: &str) -> Option<String> {
            FixtureResolver.resolve_scheme_color(name)
        }

        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            FixtureResolver.resolve_series_accent(idx)
        }

        fn theme_format_scheme(&self) -> Option<&crate::theme::ThemeFormatScheme> {
            Some(&self.format_scheme)
        }

        fn default_chart_bg(&self) -> Option<String> {
            Some("FFFFFF".to_string())
        }
    }

    fn chart_space_of(xml: &str) -> Document<'_> {
        Document::parse(xml).expect("parse chartSpace fixture")
    }

    /// §21.2.2.30 / `CT_ChartSpace`: chart-local `clrMapOvr` is a direct
    /// `CT_ColorMapping`. It replaces the application's logical color mapping,
    /// so an authored `schemeClr accent1` resolves through the declared
    /// `accent1=accent2` slot mapping for both pptx and xlsx callers.
    #[test]
    fn chart_color_map_override_remaps_explicit_and_default_series_accents() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:clrMapOvr bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2"
                accent1="accent2" accent2="accent2" accent3="accent3"
                accent4="accent4" accent5="accent5" accent6="accent6"
                hlink="hlink" folHlink="folHlink"/>
              <c:chart><c:plotArea><c:barChart>
                <c:barDir val="col"/><c:grouping val="clustered"/>
                <c:ser><c:idx val="0"/><c:order val="0"/>
                  <c:spPr><a:solidFill><a:schemeClr val="accent1"/></a:solidFill></c:spPr>
                  <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                  <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                </c:ser>
                <c:ser><c:idx val="6"/><c:order val="1"/>
                  <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                  <c:val><c:numLit><c:pt idx="0"><c:v>2</c:v></c:pt></c:numLit></c:val>
                </c:ser>
              </c:barChart></c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let chart = parse_chart_part(doc.root_element(), &FixtureResolver).expect("chart parses");

        assert_eq!(chart.series[0].color.as_deref(), Some("ED7D31"));
        assert_eq!(chart.series[1].color.as_deref(), Some("ED7D31"));
    }

    #[test]
    fn area_series_no_fill_stays_transparent_but_remains_in_the_stack() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea><c:areaChart>
                <c:grouping val="stacked"/>
                <c:ser><c:idx val="0"/><c:order val="0"/>
                  <c:spPr><a:noFill/><a:ln><a:noFill/></a:ln></c:spPr>
                  <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                  <c:val><c:numLit><c:pt idx="0"><c:v>80</c:v></c:pt></c:numLit></c:val>
                </c:ser>
              </c:areaChart>
              <c:lineChart><c:grouping val="standard"/>
                <c:ser><c:idx val="1"/><c:order val="1"/>
                  <c:spPr><a:ln><a:solidFill><a:srgbClr val="000000"/></a:solidFill></a:ln></c:spPr>
                  <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                  <c:val><c:numLit><c:pt idx="0"><c:v>85</c:v></c:pt></c:numLit></c:val>
                </c:ser>
              </c:lineChart></c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let chart = parse_chart_part(doc.root_element(), &FixtureResolver).expect("chart parses");

        assert_eq!(chart.chart_type, "stackedArea");
        assert_eq!(chart.series[0].series_type.as_deref(), Some("area"));
        assert_eq!(chart.series[0].color.as_deref(), Some("00000000"));
        assert_eq!(chart.series[0].line_hidden, Some(true));
        assert_eq!(chart.series[0].values, vec![Some(80.0)]);
        assert_eq!(chart.series[1].series_type.as_deref(), Some("line"));
        assert_eq!(chart.series[1].line_color.as_deref(), Some("000000"));
    }

    #[test]
    fn chart_space_shape_properties_without_a_fill_keep_the_host_default() {
        let chart_xml = |shape_properties: &str| {
            format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:chart><c:plotArea><c:barChart>
                    <c:barDir val="col"/><c:grouping val="clustered"/>
                    <c:ser><c:idx val="0"/><c:order val="0"/>
                      <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                      <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                    </c:ser>
                  </c:barChart></c:plotArea></c:chart>
                  {shape_properties}
                </c:chartSpace>"#
            )
        };

        // `spPr` is often present only to suppress the chart border. Since it
        // carries no fill choice, it must not also make the chart area
        // transparent.
        let line_only = chart_xml("<c:spPr><a:ln><a:noFill/></a:ln></c:spPr>");
        let doc = chart_space_of(&line_only);
        let parsed = parse_chart_part(doc.root_element(), &WhiteChartFixtureResolver)
            .expect("line-only chart parses");
        assert_eq!(parsed.chart_bg.as_deref(), Some("FFFFFF"));
        assert_eq!(parsed.chart_fill_paint_authored, None);
        assert_eq!(parsed.chart_border_hidden, Some(true));
        assert_eq!(parsed.chart_border_paint_authored, Some(true));

        // An explicit fill choice remains authoritative.
        let no_fill = chart_xml("<c:spPr><a:noFill/></c:spPr>");
        let doc = chart_space_of(&no_fill);
        let parsed = parse_chart_part(doc.root_element(), &WhiteChartFixtureResolver)
            .expect("noFill chart parses");
        assert_eq!(parsed.chart_bg, None);
        assert_eq!(parsed.chart_fill_hidden, Some(true));
        assert_eq!(parsed.chart_fill_paint_authored, Some(true));
    }

    #[test]
    fn plot_area_omitted_fill_uses_the_host_default_but_no_fill_remains_explicit() {
        let chart_xml = |plot_shape_properties: &str| {
            format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:barChart><c:barDir val="col"/><c:ser><c:idx val="0"/>
                  <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                  <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                </c:ser></c:barChart>{plot_shape_properties}
              </c:plotArea></c:chart>
            </c:chartSpace>"#
            )
        };
        let omitted = chart_xml("");
        let parsed = parse_chart_part(
            chart_space_of(&omitted).root_element(),
            &WhiteChartFixtureResolver,
        )
        .expect("plot-area chart parses");
        assert_eq!(parsed.plot_area_bg.as_deref(), Some("FFFFFF"));
        assert_eq!(parsed.plot_area_fill_automatic, Some(true));

        let no_fill = chart_xml("<c:spPr><a:noFill/></c:spPr>");
        let parsed = parse_chart_part(
            chart_space_of(&no_fill).root_element(),
            &WhiteChartFixtureResolver,
        )
        .expect("noFill plot-area chart parses");
        assert_eq!(parsed.plot_area_bg, None);
        assert_eq!(parsed.plot_area_fill_hidden, Some(true));
        assert_eq!(parsed.plot_area_fill_automatic, None);
    }

    #[test]
    fn ct_boolean_auto_title_deleted_bare_suppresses_fallback_title() {
        // §21.2.2.7 `<c:autoTitleDeleted/>` ⇒ true ⇒ the single-series name is
        // NOT promoted to a fallback chart title. A bare element must read true;
        // its absence (control) leaves the auto title, so the series name shows.
        let with_bare = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart>
                <c:autoTitleDeleted/>
                <c:plotArea><c:lineChart>
                  <c:ser><c:idx val="0"/><c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>OnlySeries</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:val><c:numRef><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:numRef></c:val></c:ser>
                </c:lineChart></c:plotArea>
              </c:chart></c:chartSpace>"#
        );
        let d = chart_space_of(&with_bare);
        let m = parse_chart_part(d.root_element(), &FixtureResolver).expect("chart");
        assert_eq!(
            m.title, None,
            "bare <c:autoTitleDeleted/> ⇒ no fallback title"
        );

        let without = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart>
                <c:plotArea><c:lineChart>
                  <c:ser><c:idx val="0"/><c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>OnlySeries</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:val><c:numRef><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:numRef></c:val></c:ser>
                </c:lineChart></c:plotArea>
              </c:chart></c:chartSpace>"#
        );
        let d2 = chart_space_of(&without);
        let m2 = parse_chart_part(d2.root_element(), &FixtureResolver).expect("chart");
        assert_eq!(
            m2.title.as_deref(),
            Some("OnlySeries"),
            "no autoTitleDeleted ⇒ series name is the fallback title"
        );
    }

    #[test]
    fn ct_boolean_chart_level_marker_bare_enables_markers() {
        // §21.2.2.33 `<c:lineChart><c:marker/>` ⇒ true ⇒ line series show markers
        // even without a per-series `<c:marker>`. A bare element must read true.
        let bare = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart>
                <c:plotArea><c:lineChart>
                  <c:marker/>
                  <c:ser><c:idx val="0"/>
                    <c:val><c:numRef><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:numRef></c:val></c:ser>
                </c:lineChart></c:plotArea>
              </c:chart></c:chartSpace>"#
        );
        let d = chart_space_of(&bare);
        let m = parse_chart_part(d.root_element(), &FixtureResolver).expect("chart");
        assert_eq!(
            m.series[0].show_marker,
            Some(true),
            "bare <c:marker/> ⇒ markers enabled"
        );

        // Control: `<c:marker val="0"/>` ⇒ markers off for a line series.
        let off = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart>
                <c:plotArea><c:lineChart>
                  <c:marker val="0"/>
                  <c:ser><c:idx val="0"/>
                    <c:val><c:numRef><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:numRef></c:val></c:ser>
                </c:lineChart></c:plotArea>
              </c:chart></c:chartSpace>"#
        );
        let d2 = chart_space_of(&off);
        let m2 = parse_chart_part(d2.root_element(), &FixtureResolver).expect("chart");
        assert_eq!(
            m2.series[0].show_marker,
            Some(false),
            "<c:marker val=\"0\"/> ⇒ markers off"
        );
    }

    #[test]
    fn chart_level_smooth_is_the_line_series_default() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart>
                <c:plotArea><c:lineChart>
                  <c:grouping val="standard"/><c:smooth/>
                  <c:ser><c:idx val="0"/><c:order val="0"/>
                    <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                  </c:ser>
                  <c:ser><c:idx val="1"/><c:order val="1"/><c:smooth val="0"/>
                    <c:val><c:numLit><c:pt idx="0"><c:v>2</c:v></c:pt></c:numLit></c:val>
                  </c:ser>
                </c:lineChart></c:plotArea>
              </c:chart></c:chartSpace>"#
        );
        let model = parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
            .expect("line chart parses");
        assert_eq!(model.series[0].smooth, Some(true));
        assert_eq!(model.series[1].smooth, Some(false));
    }

    /// (a) Bar chart with the full decoration set: title (size/bold/color),
    /// legend, styled category + value axes, gap/overlap, chartSpace border,
    /// and value-axis major gridlines. Every field asserted here is a distinct
    /// probe `parse_chart_part` wires up; a regression in any one shows here
    /// without needing a full-document golden diff.
    #[test]
    fn parse_chart_part_bar_full_decoration() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart>
                <c:title><c:tx><c:rich>
                  <a:p><a:pPr><a:defRPr sz="1800" b="1"><a:solidFill><a:srgbClr val="1b4332"/></a:solidFill></a:defRPr></a:pPr>
                  <a:r><a:t>Quarterly Revenue</a:t></a:r></a:p>
                </c:rich></c:tx></c:title>
                <c:plotArea>
                  <c:barChart>
                    <c:barDir val="col"/>
                    <c:grouping val="clustered"/>
                    <c:gapWidth val="80"/>
                    <c:overlap val="-10"/>
                    <c:ser>
                      <c:idx val="0"/>
                      <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>Revenue</c:v></c:pt></c:strCache></c:strRef></c:tx>
                      <c:spPr><a:solidFill><a:srgbClr val="2d6a4f"/></a:solidFill><a:ln w="12700"><a:solidFill><a:srgbClr val="595959"/></a:solidFill></a:ln></c:spPr>
                      <c:cat><c:strCache><c:pt idx="0"><c:v>Q1</c:v></c:pt><c:pt idx="1"><c:v>Q2</c:v></c:pt></c:strCache></c:cat>
                      <c:val><c:numCache><c:pt idx="0"><c:v>10</c:v></c:pt><c:pt idx="1"><c:v>20</c:v></c:pt></c:numCache></c:val>
                    </c:ser>
                    <c:axId val="1"/>
                    <c:axId val="2"/>
                  </c:barChart>
                  <c:catAx>
                    <c:axId val="1"/>
                    <c:axPos val="b"/>
                    <c:title><c:tx><c:rich><a:bodyPr vert="horz"/><a:p><a:r><a:t>Quarter</a:t></a:r></a:p></c:rich></c:tx></c:title>
                    <c:spPr><a:ln><a:solidFill><a:srgbClr val="808080"/></a:solidFill><a:prstDash val="dash"/></a:ln></c:spPr>
                  </c:catAx>
                  <c:valAx>
                    <c:axId val="2"/>
                    <c:axPos val="l"/>
                    <c:title><c:tx><c:rich><a:bodyPr rot="-1800000"/><a:p><a:r><a:t>Revenue</a:t></a:r></a:p></c:rich></c:tx>
                      <c:layout><c:manualLayout><c:xMode val="edge"/><c:yMode val="edge"/><c:x val="0.2"/><c:y val="0.1"/></c:manualLayout></c:layout>
                    </c:title>
                    <c:majorGridlines><c:spPr><a:ln w="3175"><a:solidFill><a:schemeClr val="accent3"/></a:solidFill></a:ln></c:spPr></c:majorGridlines>
                    <c:spPr><a:ln w="12700"><a:solidFill><a:srgbClr val="404040"/></a:solidFill><a:prstDash val="dot"/></a:ln></c:spPr>
                    <c:scaling><c:min val="0"/><c:max val="30"/></c:scaling>
                  </c:valAx>
                </c:plotArea>
                <c:legend><c:legendPos val="b"/></c:legend>
              </c:chart>
              <c:spPr><a:ln w="19050" cap="rnd"><a:solidFill><a:schemeClr val="tx1"/></a:solidFill><a:prstDash val="lgDashDotDot"/><a:miter/></a:ln></c:spPr>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let m = parse_chart_part(doc.root_element(), &FixtureResolver).expect("bar chart parses");

        assert_eq!(m.chart_type, "clusteredBar");
        assert_eq!(m.title.as_deref(), Some("Quarterly Revenue"));
        assert_eq!(m.title_font_size_hpt, Some(1800));
        assert_eq!(m.title_font_bold, Some(true));
        // `parse_chart_part` now resolves the title's `<a:solidFill>` via the
        // `ColorResolver` (schemeClr resolution was added — see
        // `extract_chart_title_color`). The fixture's title carries
        // `<a:srgbClr val="1b4332">`, which the resolver returns uppercased.
        // (This assertion previously pinned `None` as a known limitation; the
        // limitation is now fixed, so the expected value flips to the resolved
        // hex — a deliberate, visible contract change.)
        assert_eq!(m.title_font_color.as_deref(), Some("1B4332"));
        assert_eq!(m.categories, vec!["Q1".to_string(), "Q2".to_string()]);
        assert_eq!(m.series.len(), 1);
        assert_eq!(m.series[0].name, "Revenue");
        assert_eq!(m.series[0].values, vec![Some(10.0), Some(20.0)]);
        assert_eq!(m.series[0].color.as_deref(), Some("2D6A4F"));
        assert_eq!(m.series[0].line_color.as_deref(), Some("595959"));
        assert_eq!(m.series[0].line_width_emu, Some(12700));
        assert!(m.show_legend);
        assert_eq!(m.legend_pos.as_deref(), Some("b"));
        assert_eq!(m.bar_gap_width, Some(80));
        assert_eq!(m.bar_overlap, Some(-10));
        assert_eq!(m.val_min, Some(0.0));
        assert_eq!(m.val_max, Some(30.0));
        assert_eq!(m.val_axis_major_gridlines, Some(true));
        assert_eq!(m.cat_axis_major_gridlines, Some(false));
        // The value-axis `<c:majorGridlines><c:spPr><a:ln>` carries an explicit
        // `accent3` colour (resolver → A5A5A5) and a 3175 EMU (0.25 pt) width.
        assert_eq!(m.val_axis_gridline_color.as_deref(), Some("A5A5A5"));
        assert_eq!(m.val_axis_gridline_width_emu, Some(3175));
        // The category axis has no gridlines element → no gridline style.
        assert_eq!(m.cat_axis_gridline_color, None);
        assert_eq!(m.cat_axis_gridline_width_emu, None);
        assert_eq!(m.cat_axis_line_color.as_deref(), Some("808080"));
        assert_eq!(m.cat_axis_line_dash.as_deref(), Some("dash"));
        assert_eq!(m.cat_axis_line_paint_authored, Some(true));
        assert_eq!(m.val_axis_line_color.as_deref(), Some("404040"));
        assert_eq!(m.val_axis_line_width_emu, Some(12700));
        assert_eq!(m.val_axis_line_dash.as_deref(), Some("dot"));
        assert_eq!(m.val_axis_line_paint_authored, Some(true));
        // The chartSpace border is theme-aware: scheme tx1 resolves through
        // the same color resolver as other DrawingML lines.
        assert_eq!(m.chart_border_color.as_deref(), Some("000000"));
        assert_eq!(m.chart_border_width_emu, Some(19050));
        assert_eq!(m.chart_border_dash.as_deref(), Some("lgDashDotDot"));
        assert_eq!(m.chart_border_cap.as_deref(), Some("rnd"));
        assert_eq!(m.chart_border_join.as_deref(), Some("miter"));
        assert!(!m.cat_axis_hidden);
        assert!(!m.val_axis_hidden);
        assert_eq!(m.cat_axis_title_rotation, None);
        assert_eq!(m.cat_axis_title_vertical_mode.as_deref(), Some("horz"));
        assert_eq!(m.cat_axis_title_text_vertical_inset_emu, Some(91_440));
        assert_eq!(m.val_axis_title_rotation, Some(-1_800_000));
        assert_eq!(m.val_axis_title_text_vertical_inset_emu, Some(91_440));
        let val_title_layout = m
            .val_axis_title_manual_layout
            .expect("value-axis title manual layout");
        assert_eq!(val_title_layout.x, 0.2);
        assert_eq!(val_title_layout.y, 0.1);
    }

    #[test]
    fn parse_chart_part_preserves_custom_data_label_run_styles() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
              <c:lineChart><c:grouping val="standard"/><c:ser>
                <c:idx val="0"/><c:tx><c:v>Employer</c:v></c:tx>
                <c:dLbls><c:dLbl><c:idx val="0"/><c:tx><c:rich><a:p>
                  <a:pPr><a:defRPr sz="800" b="1"/></a:pPr>
                  <a:r><a:rPr sz="1200" b="1"/><a:t>Employer</a:t></a:r>
                  <a:r><a:rPr sz="1100" b="0"/><a:t> 36.0%</a:t></a:r>
                </a:p></c:rich></c:tx><c:dLblPos val="l"/>
                <c:showVal val="1"/><c:showSerName val="1"/>
                </c:dLbl></c:dLbls>
                <c:cat><c:strCache><c:pt idx="0"><c:v>Start</c:v></c:pt></c:strCache></c:cat>
                <c:val><c:numCache><c:pt idx="0"><c:v>36</c:v></c:pt></c:numCache></c:val>
              </c:ser></c:lineChart>
            </c:plotArea></c:chart></c:chartSpace>"#
        );
        let document = chart_space_of(&xml);
        let model =
            parse_chart_part(document.root_element(), &FixtureResolver).expect("line chart parses");
        let label = &model.series[0].data_label_overrides.as_ref().unwrap()[0];
        assert_eq!(label.text, "Employer 36.0%");
        assert_eq!(label.position.as_deref(), Some("l"));
        let runs = label.rich_runs.as_ref().expect("rich runs on public model");
        assert_eq!(runs[0].font_size_hpt, Some(1200));
        assert_eq!(runs[0].bold, Some(true));
        assert_eq!(runs[1].font_size_hpt, Some(1100));
        assert_eq!(runs[1].bold, Some(false));
    }

    /// A chart title may be a string reference cache rather than DrawingML
    /// rich text (§21.2.2.6 CT_Title → §21.2.2.198 CT_Tx). The cached `<c:v>`
    /// is the authored title and must win over the single-series auto title.
    #[test]
    fn parse_chart_part_uses_strref_cache_for_title() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart>
                <c:title><c:tx><c:strRef><c:f>Sheet1!$A$1</c:f><c:strCache>
                  <c:ptCount val="1"/><c:pt idx="0"><c:v>Authored cached title</c:v></c:pt>
                </c:strCache></c:strRef></c:tx></c:title>
                <c:autoTitleDeleted val="0"/>
                <c:plotArea><c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>
                  <c:ser><c:idx val="0"/>
                    <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>Series fallback</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                    <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                  </c:ser>
                </c:barChart></c:plotArea>
              </c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let model = parse_chart_part(doc.root_element(), &FixtureResolver).expect("chart parses");
        assert_eq!(model.title.as_deref(), Some("Authored cached title"));
    }

    #[test]
    fn parse_chart_part_preserves_primary_axis_display_units_and_labels() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
              <c:scatterChart><c:ser><c:idx val="0"/>
                <c:xVal><c:numLit><c:pt idx="0"><c:v>1000</c:v></c:pt></c:numLit></c:xVal>
                <c:yVal><c:numLit><c:pt idx="0"><c:v>20</c:v></c:pt></c:numLit></c:yVal>
              </c:ser></c:scatterChart>
              <c:valAx><c:axPos val="b"/><c:dispUnits><c:builtInUnit val="thousands"/>
                <c:dispUnitsLbl><c:layout><c:manualLayout><c:x val="0.7"/><c:y val="0.8"/></c:manualLayout></c:layout>
                  <c:txPr><a:bodyPr/><a:p><a:pPr><a:defRPr sz="800" b="1"><a:solidFill><a:srgbClr val="112233"/></a:solidFill><a:latin typeface="Arial"/></a:defRPr></a:pPr></a:p></c:txPr>
                </c:dispUnitsLbl></c:dispUnits></c:valAx>
              <c:valAx><c:axPos val="l"/><c:dispUnits><c:custUnit val="10"/>
                <c:dispUnitsLbl><c:tx><c:rich><a:p><a:r><a:t>per ten</a:t></a:r></a:p></c:rich></c:tx>
                  <c:txPr><a:bodyPr rot="-5400000"/><a:p><a:pPr><a:defRPr sz="900"/></a:pPr></a:p></c:txPr>
                </c:dispUnitsLbl></c:dispUnits></c:valAx>
            </c:plotArea></c:chart></c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let model = parse_chart_part(doc.root_element(), &FixtureResolver).expect("scatter parses");
        let x = model.cat_axis_display_units.expect("horizontal units");
        assert_eq!(x.divisor, 1_000.0);
        assert_eq!(x.built_in_unit.as_deref(), Some("thousands"));
        let x_label = x.label.expect("horizontal unit label");
        assert_eq!(
            x_label.manual_layout.as_ref().map(|layout| layout.x),
            Some(0.7)
        );
        assert_eq!(x_label.font_size_hpt, Some(800));
        assert_eq!(x_label.font_bold, Some(true));
        assert_eq!(x_label.font_color.as_deref(), Some("112233"));
        assert_eq!(x_label.font_face.as_deref(), Some("Arial"));

        let y = model.val_axis_display_units.expect("vertical units");
        assert_eq!(y.divisor, 10.0);
        assert_eq!(y.built_in_unit, None);
        let y_label = y.label.expect("vertical unit label");
        assert_eq!(y_label.text.as_deref(), Some("per ten"));
        assert_eq!(y_label.rotation, Some(-5_400_000));
        assert_eq!(y_label.font_size_hpt, Some(900));
    }

    /// A chart without `<c:style>` is valid (`CT_ChartSpace.style` is optional).
    /// PowerPoint opens this legacy/default-style form with black 0.75 pt axes
    /// and major gridlines. Non-Office generators commonly emit precisely this
    /// minimal form, so the shared parser must resolve the implicit formatting
    /// once for DOCX, XLSX, and PPTX rather than leave each renderer to guess.
    #[test]
    fn parse_chart_part_resolves_styleless_legacy_axis_defaults() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart>
                <c:plotArea>
                  <c:barChart>
                    <c:barDir val="col"/><c:grouping val="clustered"/>
                    <c:ser><c:idx val="0"/>
                      <c:cat><c:strLit><c:pt idx="0"><c:v>T1</c:v></c:pt></c:strLit></c:cat>
                      <c:val><c:numLit><c:pt idx="0"><c:v>10</c:v></c:pt></c:numLit></c:val>
                    </c:ser>
                  </c:barChart>
                  <c:catAx><c:delete val="0"/><c:majorTickMark val="out"/></c:catAx>
                  <c:valAx><c:delete val="0"/><c:majorGridlines/><c:majorTickMark val="out"/></c:valAx>
                </c:plotArea>
              </c:chart>
              <c:txPr><a:bodyPr/><a:p><a:pPr><a:defRPr sz="1800"/></a:pPr></a:p></c:txPr>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let m = parse_chart_part(doc.root_element(), &FixtureResolver).expect("bar chart parses");

        assert_eq!(m.cat_axis_font_size_hpt, Some(1800));
        assert_eq!(m.val_axis_font_size_hpt, Some(1800));
        assert_eq!(m.cat_axis_font_color.as_deref(), Some("000000"));
        assert_eq!(m.val_axis_font_color.as_deref(), Some("000000"));
        assert_eq!(m.cat_axis_line_color.as_deref(), Some("000000"));
        assert_eq!(m.val_axis_line_color.as_deref(), Some("000000"));
        assert_eq!(m.cat_axis_line_width_emu, Some(9525));
        assert_eq!(m.val_axis_line_width_emu, Some(9525));
        assert_eq!(m.cat_axis_line_paint_authored, None);
        assert_eq!(m.val_axis_line_paint_authored, None);
        assert_eq!(m.val_axis_gridline_color.as_deref(), Some("000000"));
        assert_eq!(m.val_axis_gridline_width_emu, Some(9525));

        let no_fill_xml = xml.replace(
            "<c:majorGridlines/>",
            "<c:majorGridlines><c:spPr><a:ln><a:noFill/></a:ln></c:spPr></c:majorGridlines>",
        );
        let no_fill_doc = chart_space_of(&no_fill_xml);
        let no_fill_model = parse_chart_part(no_fill_doc.root_element(), &FixtureResolver)
            .expect("no-fill chart parses");
        assert_eq!(no_fill_model.val_axis_major_gridlines, Some(false));
        assert_eq!(no_fill_model.val_axis_gridline_color, None);
        assert_eq!(no_fill_model.val_axis_gridline_width_emu, None);

        let no_fill_axis_xml = xml.replace(
            "<c:valAx><c:delete val=\"0\"/><c:majorGridlines/><c:majorTickMark val=\"out\"/></c:valAx>",
            "<c:valAx><c:delete val=\"0\"/><c:majorGridlines/><c:majorTickMark val=\"out\"/><c:spPr><a:ln><a:noFill/></a:ln></c:spPr></c:valAx>",
        );
        let no_fill_axis_doc = chart_space_of(&no_fill_axis_xml);
        let no_fill_axis_model =
            parse_chart_part(no_fill_axis_doc.root_element(), &FixtureResolver)
                .expect("no-fill axis chart parses");
        assert!(no_fill_axis_model.val_axis_line_hidden);
        assert_eq!(no_fill_axis_model.val_axis_major_tick_mark, "out");
        assert!(!no_fill_axis_model.val_axis_hidden);
    }

    #[test]
    fn style_two_axis_overlay_inherits_first_theme_line_width() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:style val="2"/>
              <c:chart><c:plotArea><c:barChart><c:barDir val="col"/><c:ser>
                <c:idx val="0"/><c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
              </c:ser></c:barChart>
              <c:catAx><c:spPr><a:ln><a:solidFill><a:srgbClr val="000000"/></a:solidFill></a:ln></c:spPr></c:catAx>
              <c:valAx><c:spPr><a:ln><a:solidFill><a:srgbClr val="000000"/></a:solidFill></a:ln></c:spPr></c:valAx>
              </c:plotArea></c:chart></c:chartSpace>"#,
        );
        let theme = format!(
            r#"<a:theme xmlns:a="{A_NS}"><a:themeElements><a:fmtScheme name="Office">
              <a:fillStyleLst/><a:lnStyleLst><a:ln w="12700"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln></a:lnStyleLst>
              <a:effectStyleLst/><a:bgFillStyleLst/>
            </a:fmtScheme></a:themeElements></a:theme>"#,
        );
        let resolver = FormatSchemeFixtureResolver {
            format_scheme: crate::theme::ThemeFormatScheme::parse(&theme),
        };
        let doc = chart_space_of(&xml);
        let model = parse_chart_part(doc.root_element(), &resolver).expect("chart parses");
        assert_eq!(model.cat_axis_line_width_emu, Some(12700));
        assert_eq!(model.val_axis_line_width_emu, Some(12700));

        let other_style = xml.replace("<c:style val=\"2\"/>", "<c:style val=\"10\"/>");
        let other_doc = chart_space_of(&other_style);
        let other = parse_chart_part(other_doc.root_element(), &resolver).expect("chart parses");
        assert_eq!(other.cat_axis_line_width_emu, None);
        assert_eq!(other.val_axis_line_width_emu, None);

        let absent_overlay = xml.replace(
            "<c:catAx><c:spPr><a:ln><a:solidFill><a:srgbClr val=\"000000\"/></a:solidFill></a:ln></c:spPr></c:catAx>",
            "<c:catAx/>",
        );
        let absent_doc = chart_space_of(&absent_overlay);
        let absent = parse_chart_part(absent_doc.root_element(), &resolver).expect("chart parses");
        assert_eq!(absent.cat_axis_line_width_emu, None);

        let explicit_width = xml.replacen("<a:ln>", "<a:ln w=\"9525\">", 1);
        let explicit_doc = chart_space_of(&explicit_width);
        let explicit =
            parse_chart_part(explicit_doc.root_element(), &resolver).expect("chart parses");
        assert_eq!(explicit.cat_axis_line_width_emu, Some(9525));
        assert_eq!(explicit.val_axis_line_width_emu, Some(12700));

        let no_fill = xml.replace(
            "<a:ln><a:solidFill><a:srgbClr val=\"000000\"/></a:solidFill></a:ln>",
            "<a:ln><a:noFill/></a:ln>",
        );
        let no_fill_doc = chart_space_of(&no_fill);
        let no_fill_model =
            parse_chart_part(no_fill_doc.root_element(), &resolver).expect("chart parses");
        assert!(no_fill_model.cat_axis_line_hidden);
        assert!(no_fill_model.val_axis_line_hidden);
        assert_eq!(no_fill_model.cat_axis_line_width_emu, None);
        assert_eq!(no_fill_model.val_axis_line_width_emu, None);

        for line in ["<a:ln/>", "<a:ln><a:prstDash val=\"dash\"/></a:ln>"] {
            let unresolved_overlay = xml.replace(
                "<a:ln><a:solidFill><a:srgbClr val=\"000000\"/></a:solidFill></a:ln>",
                line,
            );
            let unresolved_doc = chart_space_of(&unresolved_overlay);
            let unresolved =
                parse_chart_part(unresolved_doc.root_element(), &resolver).expect("chart parses");
            assert_eq!(unresolved.cat_axis_line_color, None);
            assert_eq!(unresolved.val_axis_line_color, None);
            assert_eq!(unresolved.cat_axis_line_width_emu, None);
            assert_eq!(unresolved.val_axis_line_width_emu, None);
            assert_eq!(unresolved.cat_axis_line_paint_authored, Some(true));
            assert_eq!(unresolved.val_axis_line_paint_authored, Some(true));
        }
    }

    /// (b) Combo chart: a bar series on the primary value axis plus a line
    /// series bound to a SECONDARY value axis (`axPos="r"`). Verifies the
    /// series↔axId binding produces `series_type: "line"` and
    /// `use_secondary_axis: true` on the line series only, and that
    /// `secondary_val_axis` is populated from the right-hand `<c:valAx>`.
    #[test]
    fn parse_chart_part_combo_with_secondary_axis() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:barChart>
                  <c:barDir val="col"/>
                  <c:grouping val="clustered"/>
                  <c:ser>
                    <c:idx val="0"/>
                    <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>Units</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:cat><c:strCache><c:pt idx="0"><c:v>Jan</c:v></c:pt><c:pt idx="1"><c:v>Feb</c:v></c:pt></c:strCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>5</c:v></c:pt><c:pt idx="1"><c:v>7</c:v></c:pt></c:numCache></c:val>
                  </c:ser>
                  <c:axId val="1"/>
                  <c:axId val="2"/>
                </c:barChart>
                <c:lineChart>
                  <c:grouping val="standard"/>
                  <c:ser>
                    <c:idx val="1"/>
                    <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>Margin %</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:cat><c:strCache><c:pt idx="0"><c:v>Jan</c:v></c:pt><c:pt idx="1"><c:v>Feb</c:v></c:pt></c:strCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>0.3</c:v></c:pt><c:pt idx="1"><c:v>0.4</c:v></c:pt></c:numCache></c:val>
                  </c:ser>
                  <c:axId val="1"/>
                  <c:axId val="3"/>
                </c:lineChart>
                <c:catAx><c:axId val="1"/><c:axPos val="b"/></c:catAx>
                <c:valAx>
                  <c:axId val="2"/>
                  <c:axPos val="l"/>
                  <c:crosses val="autoZero"/>
                </c:valAx>
                <c:valAx>
                  <c:axId val="3"/>
                  <c:axPos val="r"/>
                  <c:crosses val="max"/>
                  <c:scaling><c:logBase val="10"/><c:orientation val="maxMin"/><c:min val="0.01"/><c:max val="1"/></c:scaling>
                  <c:tickLblPos val="none"/>
                  <c:spPr><a:ln w="19050"><a:solidFill><a:srgbClr val="ABCDEF"/></a:solidFill><a:prstDash val="sysDot"/></a:ln></c:spPr>
                  <c:majorGridlines><c:spPr><a:ln w="9525"><a:solidFill><a:srgbClr val="654321"/></a:solidFill><a:prstDash val="dash"/></a:ln></c:spPr></c:majorGridlines>
                  <c:majorUnit val="0.25"/>
                  <c:minorUnit val="0.05"/>
                  <c:minorTickMark val="cross"/>
                  <c:minorGridlines><c:spPr><a:ln w="12700"><a:solidFill><a:srgbClr val="123456"/></a:solidFill><a:prstDash val="dot"/></a:ln></c:spPr></c:minorGridlines>
                  <c:txPr><a:p><a:pPr><a:defRPr b="1"><a:latin typeface="Tick Face"/></a:defRPr></a:pPr></a:p></c:txPr>
                  <c:title><c:tx><c:rich><a:bodyPr vert="vert"/><a:p><a:r><a:rPr sz="900" b="0"><a:latin typeface="Title Face"/></a:rPr><a:t>Margin</a:t></a:r></a:p></c:rich></c:tx>
                    <c:layout><c:manualLayout><c:x val="0.1"/><c:y val="0.2"/></c:manualLayout></c:layout>
                  </c:title>
                </c:valAx>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let m = parse_chart_part(doc.root_element(), &FixtureResolver).expect("combo chart parses");

        assert_eq!(m.chart_type, "clusteredBar");
        assert_eq!(m.series.len(), 2);

        let bar_series = &m.series[0];
        assert_eq!(bar_series.name, "Units");
        // Every series now carries its chart-group type (the renderer keys line
        // vs. non-line off this; a bar series is `Some("bar")`, treated as
        // non-line, identical in rendering to the old `None`).
        assert_eq!(bar_series.series_type.as_deref(), Some("bar"));
        assert_eq!(bar_series.use_secondary_axis, None);

        let line_series = &m.series[1];
        assert_eq!(line_series.name, "Margin %");
        assert_eq!(line_series.series_type.as_deref(), Some("line"));
        assert_eq!(line_series.use_secondary_axis, Some(true));

        let sec = m.secondary_val_axis.expect("secondary axis populated");
        assert_eq!(sec.min, Some(0.01));
        assert_eq!(sec.max, Some(1.0));
        assert_eq!(sec.title.as_deref(), Some("Margin"));
        assert!(!sec.hidden);
        assert_eq!(sec.font_face.as_deref(), Some("Tick Face"));
        assert_eq!(sec.font_bold, Some(true));
        assert_eq!(sec.log_base, Some(10.0));
        assert_eq!(sec.orientation.as_deref(), Some("maxMin"));
        assert_eq!(sec.tick_label_pos.as_deref(), Some("none"));
        assert_eq!(sec.line_color.as_deref(), Some("ABCDEF"));
        assert_eq!(sec.line_width_emu, Some(19050));
        assert_eq!(sec.line_dash.as_deref(), Some("sysDot"));
        assert_eq!(sec.crosses.as_deref(), Some("max"));
        assert_eq!(sec.crosses_at, None);
        assert!(sec.major_gridlines);
        assert_eq!(sec.major_gridline_color.as_deref(), Some("654321"));
        assert_eq!(sec.major_gridline_width_emu, Some(9525));
        assert_eq!(sec.major_gridline_dash.as_deref(), Some("dash"));
        assert_eq!(sec.minor_tick_mark.as_deref(), Some("cross"));
        assert!(sec.minor_gridlines);
        assert_eq!(sec.minor_gridline_color.as_deref(), Some("123456"));
        assert_eq!(sec.minor_gridline_width_emu, Some(12700));
        assert_eq!(sec.minor_gridline_dash.as_deref(), Some("dot"));
        assert_eq!(sec.minor_unit, Some(0.05));
        assert_eq!(sec.title_font_face.as_deref(), Some("Title Face"));
        assert_eq!(sec.title_font_size_hpt, Some(900));
        assert_eq!(sec.title_font_bold, Some(false));
        assert_eq!(sec.title_rotation, None);
        assert_eq!(sec.title_vertical_mode.as_deref(), Some("vert"));
        assert_eq!(
            sec.title_manual_layout.as_ref().map(|layout| layout.x),
            Some(0.1)
        );
        // #738: an explicit `<c:majorUnit>` on the secondary axis (§21.2.2.103)
        // is threaded into the model (was silently dropped before).
        assert_eq!(sec.major_unit, Some(0.25));
        // The primary value axis declared no majorUnit → stays None.
        assert_eq!(m.val_axis_major_unit, None);
    }

    #[test]
    fn parse_chart_part_two_bar_groups_retains_top_category_axis() {
        let group = |idx: usize, name: &str, cat_axis: u32, val_axis: u32| {
            format!(
                r#"<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>
              <c:ser><c:idx val="{idx}"/><c:tx><c:v>{name}</c:v></c:tx>
                <c:cat><c:strLit><c:ptCount val="1"/><c:pt idx="0"><c:v>{name} Cat</c:v></c:pt></c:strLit></c:cat>
                <c:val><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>{}</c:v></c:pt></c:numLit></c:val>
              </c:ser><c:axId val="{cat_axis}"/><c:axId val="{val_axis}"/></c:barChart>"#,
                if idx == 0 { 100 } else { 1 },
            )
        };
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
              {}{}
              <c:catAx><c:axId val="1"/><c:axPos val="b"/><c:crossAx val="2"/></c:catAx>
              <c:valAx><c:axId val="2"/><c:axPos val="l"/><c:crossAx val="1"/></c:valAx>
              <c:catAx><c:axId val="3"/><c:axPos val="t"/><c:lblAlgn val="r"/><c:lblOffset val="250%"/>
                <c:tickLblSkip val="2"/><c:tickMarkSkip val="3"/>
                <c:title><c:tx><c:rich><a:p><a:r><a:t>Top Categories</a:t></a:r></a:p></c:rich></c:tx></c:title>
                <c:crossAx val="4"/><c:crosses val="max"/></c:catAx>
              <c:valAx><c:axId val="4"/><c:axPos val="r"/><c:crossAx val="3"/><c:crosses val="max"/>
                <c:scaling><c:min val="0"/><c:max val="1"/></c:scaling></c:valAx>
            </c:plotArea></c:chart></c:chartSpace>"#,
            group(0, "Primary", 1, 2),
            group(1, "Secondary", 3, 4),
        );
        let doc = chart_space_of(&xml);
        let model =
            parse_chart_part(doc.root_element(), &FixtureResolver).expect("dual bar axes parse");

        assert_eq!(model.series[0].use_secondary_axis, None);
        assert_eq!(model.series[1].use_secondary_axis, Some(true));
        let top = model.secondary_cat_axis.expect("top category axis");
        assert_eq!(top.title.as_deref(), Some("Top Categories"));
        assert_eq!(top.label_alignment.as_deref(), Some("r"));
        assert_eq!(top.label_offset_percent, Some(250));
        assert_eq!(top.tick_label_skip, Some(2));
        assert_eq!(top.tick_mark_skip, Some(3));
        let right = model.secondary_val_axis.expect("right value axis");
        assert_eq!(right.max, Some(1.0));
    }

    #[test]
    fn parse_category_axis_label_alignment_and_offset_contracts() {
        let parse_axis = |axis_name: &str, authored: &str| {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
                  <c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>
                    <c:ser><c:idx val="0"/><c:cat><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                      <c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val></c:ser>
                    <c:axId val="1"/><c:axId val="2"/></c:barChart>
                  <c:{axis_name}><c:axId val="1"/><c:axPos val="b"/>{authored}<c:crossAx val="2"/></c:{axis_name}>
                  <c:valAx><c:axId val="2"/><c:axPos val="l"/><c:crossAx val="1"/></c:valAx>
                </c:plotArea></c:chart></c:chartSpace>"#,
            );
            let doc = chart_space_of(&xml);
            parse_chart_part(doc.root_element(), &FixtureResolver).expect("axis parses")
        };

        let strict = parse_axis("catAx", r#"<c:lblAlgn val="r"/><c:lblOffset val="250%"/>"#);
        assert_eq!(strict.cat_axis_label_alignment.as_deref(), Some("r"));
        assert_eq!(strict.cat_axis_label_offset_percent, Some(250));

        let transitional = parse_axis("catAx", r#"<c:lblAlgn val="l"/><c:lblOffset val="0"/>"#);
        assert_eq!(transitional.cat_axis_label_alignment.as_deref(), Some("l"));
        assert_eq!(transitional.cat_axis_label_offset_percent, Some(0));

        let bare_date = parse_axis("dateAx", r#"<c:lblOffset/>"#);
        assert_eq!(bare_date.cat_axis_label_alignment, None);
        assert_eq!(bare_date.cat_axis_label_offset_percent, Some(100));

        let invalid = parse_axis(
            "catAx",
            r#"<c:lblAlgn val="justify"/><c:lblOffset val="1001"/>"#,
        );
        assert_eq!(invalid.cat_axis_label_alignment, None);
        assert_eq!(invalid.cat_axis_label_offset_percent, None);

        let omitted = parse_axis("catAx", "");
        assert_eq!(omitted.cat_axis_label_alignment, None);
        assert_eq!(omitted.cat_axis_label_offset_percent, None);
    }

    #[test]
    fn parse_chart_part_bar_scatter_combo_keeps_xy_sources_and_both_numeric_axes() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:barChart><c:barDir val="bar"/><c:grouping val="clustered"/>
                  <c:ser><c:idx val="0"/>
                    <c:cat><c:strLit><c:pt idx="0"><c:v>Top</c:v></c:pt><c:pt idx="1"><c:v>Bottom</c:v></c:pt></c:strLit></c:cat>
                    <c:val><c:numLit><c:pt idx="0"><c:v>0</c:v></c:pt><c:pt idx="1"><c:v>0</c:v></c:pt></c:numLit></c:val>
                  </c:ser><c:axId val="1"/><c:axId val="2"/>
                </c:barChart>
                <c:scatterChart><c:scatterStyle val="marker"/>
                  <c:ser><c:idx val="1"/>
                    <c:marker><c:symbol val="circle"/></c:marker>
                    <c:xVal><c:numLit><c:formatCode>0%</c:formatCode><c:pt idx="0" formatCode="0%"><c:v>0.15</c:v></c:pt><c:pt idx="1" formatCode="0.0%"><c:v>0.83</c:v></c:pt></c:numLit></c:xVal>
                    <c:yVal><c:numLit><c:pt idx="0"><c:v>2</c:v></c:pt><c:pt idx="1"><c:v>1</c:v></c:pt></c:numLit></c:yVal>
                  </c:ser><c:axId val="3"/><c:axId val="4"/>
                </c:scatterChart>
                <c:catAx><c:axId val="1"/><c:axPos val="l"/><c:tickLblSkip val="2"/><c:tickMarkSkip val="3"/></c:catAx>
                <c:valAx><c:axId val="2"/><c:axPos val="b"/><c:scaling><c:max val="1.4"/></c:scaling></c:valAx>
                <c:valAx><c:axId val="3"/><c:axPos val="b"/><c:delete val="1"/></c:valAx>
                <c:valAx><c:axId val="4"/><c:axPos val="r"/><c:delete val="1"/><c:scaling><c:min val="0"/><c:max val="2"/></c:scaling></c:valAx>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let model = parse_chart_part(doc.root_element(), &FixtureResolver)
            .expect("bar/scatter combo parses");

        assert_eq!(model.chart_type, "clusteredBarH");
        assert_eq!(model.cat_axis_tick_label_skip, Some(2));
        assert_eq!(model.cat_axis_tick_mark_skip, Some(3));
        let scatter = &model.series[1];
        assert_eq!(scatter.series_type.as_deref(), Some("scatter"));
        assert_eq!(
            scatter.categories.as_deref(),
            Some(&["0.15".into(), "0.83".into()][..])
        );
        assert_eq!(scatter.values, vec![Some(2.0), Some(1.0)]);
        assert_eq!(scatter.use_secondary_axis, Some(true));
        assert_eq!(scatter.show_marker, Some(true));
        assert_eq!(scatter.cat_format_code.as_deref(), Some("0%"));
        assert_eq!(
            scatter.cat_format_codes.as_deref(),
            Some(&[Some("0%".into()), Some("0.0%".into())][..])
        );
        assert_eq!(
            model.secondary_cat_axis.as_ref().and_then(|axis| axis.max),
            None
        );
        let y_axis = model.secondary_val_axis.expect("scatter Y axis parsed");
        assert_eq!((y_axis.min, y_axis.max), (Some(0.0), Some(2.0)));
    }

    #[test]
    fn parse_chart_part_two_scatter_groups_preserves_secondary_xy_axes() {
        let scatter = |idx: usize, x_axis: u32, y_axis: u32, x: f64, y: f64| {
            format!(
                r#"<c:scatterChart><c:scatterStyle val="marker"/>
                  <c:ser><c:idx val="{idx}"/>
                    <c:xVal><c:numLit><c:pt idx="0"><c:v>{x}</c:v></c:pt></c:numLit></c:xVal>
                    <c:yVal><c:numLit><c:pt idx="0"><c:v>{y}</c:v></c:pt></c:numLit></c:yVal>
                  </c:ser><c:axId val="{x_axis}"/><c:axId val="{y_axis}"/>
                </c:scatterChart>"#,
            )
        };
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
              {}{}
              <c:valAx><c:axId val="1"/><c:axPos val="b"/><c:crossAx val="2"/>
                <c:dispUnits><c:builtInUnit val="thousands"/></c:dispUnits></c:valAx>
              <c:valAx><c:axId val="2"/><c:axPos val="l"/><c:crossAx val="1"/>
                <c:dispUnits><c:builtInUnit val="hundreds"/></c:dispUnits></c:valAx>
              <c:valAx><c:axId val="3"/><c:axPos val="t"/><c:crossAx val="4"/>
                <c:dispUnits><c:custUnit val="1000"/></c:dispUnits></c:valAx>
              <c:valAx><c:axId val="4"/><c:axPos val="r"/><c:crossAx val="3"/>
                <c:dispUnits><c:custUnit val="10"/></c:dispUnits></c:valAx>
            </c:plotArea></c:chart></c:chartSpace>"#,
            scatter(0, 1, 2, 1000.0, 100.0),
            scatter(1, 3, 4, 2000.0, 20.0),
        );
        let doc = chart_space_of(&xml);
        let model = parse_chart_part(doc.root_element(), &FixtureResolver)
            .expect("dual scatter groups parse");

        assert_eq!(model.series[0].use_secondary_axis, None);
        assert_eq!(model.series[1].use_secondary_axis, Some(true));
        assert_eq!(
            model
                .secondary_cat_axis
                .as_ref()
                .and_then(|axis| axis.display_units.as_ref())
                .map(|units| units.divisor),
            Some(1000.0),
        );
        assert_eq!(
            model
                .secondary_val_axis
                .as_ref()
                .and_then(|axis| axis.display_units.as_ref())
                .map(|units| units.divisor),
            Some(10.0),
        );
    }

    /// (c) Doughnut chart with per-point `<c:dPt>` colors, `showPercent`, and
    /// `holeSize`/`firstSliceAng`. Doughnut (not pie) is used because
    /// `extract_hole_size` only ever matches a `<c:doughnutChart>` — a pie
    /// fixture would leave `hole_size` permanently `None`.
    #[test]
    fn parse_chart_part_doughnut_dpt_colors_and_geometry() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:doughnutChart>
                  <c:holeSize val="45"/>
                  <c:firstSliceAng val="90"/>
                  <c:ser>
                    <c:idx val="0"/>
                    <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>Share</c:v></c:pt></c:strCache></c:strRef></c:tx>
                    <c:dPt><c:idx val="0"/><c:spPr><a:solidFill><a:srgbClr val="ff0000"/></a:solidFill></c:spPr></c:dPt>
                    <c:dPt><c:idx val="1"/><c:spPr><a:solidFill><a:srgbClr val="00ff00"/></a:solidFill></c:spPr></c:dPt>
                    <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt></c:strCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>60</c:v></c:pt><c:pt idx="1"><c:v>40</c:v></c:pt></c:numCache></c:val>
                    <c:dLbls><c:showPercent val="1"/></c:dLbls>
                  </c:ser>
                </c:doughnutChart>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let m =
            parse_chart_part(doc.root_element(), &FixtureResolver).expect("doughnut chart parses");

        assert_eq!(m.chart_type, "doughnut");
        assert_eq!(m.hole_size, Some(45));
        assert_eq!(m.first_slice_angle, Some(90));
        assert!(!m.show_data_labels);
        assert_eq!(
            m.series[0]
                .series_data_labels
                .as_ref()
                .map(|labels| labels.show_percent),
            Some(true)
        );

        let colors = m.series[0]
            .data_point_colors
            .as_ref()
            .expect("dPt colors populated");
        assert_eq!(colors[0].as_deref(), Some("FF0000"));
        assert_eq!(colors[1].as_deref(), Some("00FF00"));
    }

    /// (d) A date-category axis (`<c:dateAx>` instead of `<c:catAx>`) combined
    /// with `<c:date1904/>`. `parse_chart_part` treats `dateAx` identically to
    /// `catAx` for every cat-axis probe (hidden/format-code/etc.) — this pins
    /// that the dateAx path is actually reached (not silently skipped because
    /// the finder only looked for `catAx`).
    #[test]
    fn parse_chart_part_date_axis_and_date1904() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:date1904/>
              <c:chart><c:plotArea>
                <c:lineChart>
                  <c:grouping val="standard"/>
                  <c:ser>
                    <c:idx val="0"/>
                    <c:tx><c:v>Temp</c:v></c:tx>
                    <c:cat><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>21</c:v></c:pt><c:pt idx="1"><c:v>23</c:v></c:pt></c:numCache></c:val>
                  </c:ser>
                </c:lineChart>
                <c:dateAx>
                  <c:axPos val="b"/>
                  <c:numFmt formatCode="m/d/yyyy"/>
                  <c:baseTimeUnit val="months"/>
                  <c:majorUnit val="1.5"/>
                  <c:majorTimeUnit val="months"/>
                  <c:minorUnit val="0.5"/>
                  <c:minorTimeUnit val="months"/>
                </c:dateAx>
                <c:valAx><c:axPos val="l"/></c:valAx>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let doc = chart_space_of(&xml);
        let m =
            parse_chart_part(doc.root_element(), &FixtureResolver).expect("dateAx chart parses");

        assert_eq!(m.chart_type, "line");
        assert!(m.date1904);
        assert_eq!(m.cat_axis_format_code.as_deref(), Some("m/d/yyyy"));
        assert_eq!(m.cat_axis_is_date, Some(true));
        assert_eq!(m.cat_axis_base_time_unit.as_deref(), Some("months"));
        assert_eq!(m.cat_axis_major_unit, Some(1.5));
        assert_eq!(m.cat_axis_major_time_unit.as_deref(), Some("months"));
        assert_eq!(m.cat_axis_minor_unit, Some(0.5));
        assert_eq!(m.cat_axis_minor_time_unit.as_deref(), Some("months"));
        assert!(!m.cat_axis_hidden);
    }

    /// ECMA-376 Part 1 `c:dTable` (`CT_DTable`): the data table is
    /// authored on `c:plotArea`, independently from the legend and axes. Its
    /// four CT_Boolean border/key switches and DrawingML text defaults must
    /// survive the shared parser so DOCX/XLSX/PPTX charts use one model.
    #[test]
    fn parse_chart_part_data_table_properties() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:barChart>
                  <c:barDir val="col"/><c:grouping val="clustered"/>
                  <c:ser><c:idx val="0"/>
                    <c:tx><c:v>Sales</c:v></c:tx>
                    <c:cat><c:strCache><c:pt idx="0"><c:v>Jan</c:v></c:pt></c:strCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>10</c:v></c:pt></c:numCache></c:val>
                  </c:ser>
                </c:barChart>
                <c:catAx><c:axPos val="b"/></c:catAx>
                <c:valAx><c:axPos val="l"/></c:valAx>
                <c:dTable>
                  <c:showHorzBorder/>
                  <c:showVertBorder val="0"/>
                  <c:showOutline val="1"/>
                  <c:showKeys val="1"/>
                  <c:spPr><a:solidFill><a:srgbClr val="FFF2CC"/></a:solidFill><a:ln w="12700"><a:solidFill><a:srgbClr val="445566"/></a:solidFill><a:prstDash val="dash"/></a:ln></c:spPr>
                  <c:txPr><a:bodyPr/><a:lstStyle/><a:p><a:pPr><a:defRPr sz="1000" b="1" i="1"><a:solidFill><a:srgbClr val="112233"/></a:solidFill><a:latin typeface="Aptos"/></a:defRPr></a:pPr></a:p></c:txPr>
                </c:dTable>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let model = parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
            .expect("data-table chart parses");
        let table = model.data_table.expect("c:dTable preserved");
        assert!(table.show_horizontal_border);
        assert!(!table.show_vertical_border);
        assert!(table.show_outline);
        assert!(table.show_keys);
        assert_eq!(table.font_size_hpt, Some(1000));
        assert_eq!(table.font_face.as_deref(), Some("Aptos"));
        assert_eq!(table.font_color.as_deref(), Some("112233"));
        assert_eq!(table.font_bold, Some(true));
        assert_eq!(table.font_italic, Some(true));
        assert_eq!(table.fill_color.as_deref(), Some("FFF2CC"));
        assert!(matches!(
            table.fill,
            Some(ChartStyleFill::Solid { ref color }) if color == "FFF2CC"
        ));
        assert_eq!(table.fill_hidden, None);
        assert_eq!(table.fill_paint_authored, Some(true));
        assert_eq!(table.line_color.as_deref(), Some("445566"));
        assert_eq!(table.line_width_emu, Some(12700));
        assert_eq!(table.line_dash.as_deref(), Some("dash"));
    }

    /// DrawingML `spPr` is not a solid-color-only grammar. Preserve the
    /// authored recipe/noFill provenance in the common model even though the
    /// desktop-Excel text-box extent is currently rendered only for the
    /// separately verified solid subset.
    #[test]
    fn parse_chart_data_table_preserves_non_solid_fill_provenance() {
        let parse_table = |shape: &str| {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:chart><c:plotArea>
                    <c:barChart><c:barDir val="col"/><c:ser><c:idx val="0"/>
                      <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt></c:strCache></c:cat>
                      <c:val><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:val>
                    </c:ser></c:barChart>
                    <c:dTable><c:spPr>{shape}</c:spPr></c:dTable>
                  </c:plotArea></c:chart>
                </c:chartSpace>"#
            );
            parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
                .expect("data-table chart parses")
                .data_table
                .expect("c:dTable preserved")
        };

        let gradient = parse_table(
            r#"<a:gradFill><a:gsLst>
              <a:gs pos="0"><a:srgbClr val="112233"/></a:gs>
              <a:gs pos="100000"><a:srgbClr val="AABBCC"/></a:gs>
            </a:gsLst><a:lin ang="5400000"/></a:gradFill>"#,
        );
        assert!(matches!(
            gradient.fill,
            Some(ChartStyleFill::Gradient { .. })
        ));
        assert_eq!(gradient.fill_hidden, None);
        assert_eq!(gradient.fill_paint_authored, Some(true));

        let no_fill = parse_table("<a:noFill/>");
        assert_eq!(no_fill.fill, None);
        assert_eq!(no_fill.fill_color, None);
        assert_eq!(no_fill.fill_hidden, Some(true));
        assert_eq!(no_fill.fill_paint_authored, Some(true));
    }

    #[test]
    fn parse_chart_data_table_bounds_gradient_before_expansion() {
        let chart = |stop_count: usize, trailing_fill: &str| {
            let stops = (0..stop_count)
                .map(|index| format!(r#"<a:gs pos="{index}"><a:srgbClr val="112233"/></a:gs>"#,))
                .collect::<String>();
            format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:chart><c:plotArea>
                    <c:barChart><c:barDir val="col"/><c:ser><c:idx val="0"/>
                      <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt></c:strCache></c:cat>
                      <c:val><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:val>
                    </c:ser></c:barChart>
                    <c:dTable><c:spPr><a:gradFill><a:gsLst>{stops}</a:gsLst></a:gradFill>{trailing_fill}</c:spPr></c:dTable>
                  </c:plotArea></c:chart>
                </c:chartSpace>"#,
            )
        };

        let exact_xml = chart(MAX_CHART_PAINT_RECIPE_COMPONENTS, "");
        let exact = parse_chart_part(chart_space_of(&exact_xml).root_element(), &FixtureResolver)
            .expect("paint recipe at the shared ceiling parses");
        assert!(matches!(
            exact.data_table.and_then(|table| table.fill),
            Some(ChartStyleFill::Gradient { ref stops, .. })
                if stops.len() == MAX_CHART_PAINT_RECIPE_COMPONENTS
        ));

        for trailing_fill in ["", r#"<a:pattFill prst="diagCross"/>"#, "<a:blipFill/>"] {
            let oversized_xml = chart(MAX_CHART_PAINT_RECIPE_COMPONENTS + 1, trailing_fill);
            assert!(parse_chart_part(
                chart_space_of(&oversized_xml).root_element(),
                &FixtureResolver,
            )
            .is_none());
        }
    }

    /// `c:invertIfNegative` and the Office 2010 alternate fill extension are
    /// series formatting, not XLSX viewer policy. Preserve them in the shared
    /// chart model so every DrawingML chart host paints negative bars alike.
    #[test]
    fn parse_chart_part_negative_bar_alternate_fill() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"
                 xmlns:c14="http://schemas.microsoft.com/office/drawing/2007/8/2/chart">
              <c:chart><c:plotArea><c:barChart>
                <c:barDir val="col"/><c:grouping val="clustered"/>
                <c:ser><c:idx val="0"/><c:tx><c:v>Profit</c:v></c:tx>
                  <c:spPr><a:solidFill><a:srgbClr val="4472C4"/></a:solidFill></c:spPr>
                  <c:invertIfNegative/>
                  <c:val><c:numCache><c:pt idx="0"><c:v>-3</c:v></c:pt></c:numCache></c:val>
                  <c:extLst><c:ext uri="invert"><c14:invertSolidFillFmt>
                    <c14:spPr><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill></c14:spPr>
                  </c14:invertSolidFillFmt></c:ext></c:extLst>
                </c:ser>
              </c:barChart></c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let model = parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
            .expect("negative-fill chart parses");
        let series = &model.series[0];
        assert_eq!(series.invert_if_negative, Some(true));
        assert_eq!(
            series.inverted_fill,
            Some(ChartStyleFill::Solid {
                color: "FFFFFF".to_string(),
            })
        );
        assert_eq!(series.inverted_fill_hidden, None);
        assert_eq!(series.inverted_fill_authored, Some(true));
        assert_eq!(series.inverted_line_color, None);
        assert_eq!(series.inverted_line_width_emu, None);
        assert_eq!(series.inverted_line_hidden, None);
        assert_eq!(series.inverted_line_authored, Some(false));
    }

    /// Excel's implicit classic style is not serialized when a bare chart has
    /// no `<c:style>` or series/point formatting.  The Office-observed sign
    /// mirror pair shows that the all-negative chart becomes outline-only, while the
    /// positive mirror remains an ordinary accent-filled column.  Preserve the
    /// observed effective paint without extending it to mixed-sign or authored
    /// series, whose Office defaults were not part of that boundary set.
    #[test]
    fn parse_chart_part_applies_bounded_outline_only_negative_default() {
        fn parsed_series(value: i32, authored_fill: bool) -> ChartSeries {
            let sp_pr = if authored_fill {
                r#"<c:spPr><a:solidFill><a:srgbClr val="FF0000"/></a:solidFill></c:spPr>"#
            } else {
                ""
            };
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:chart><c:plotArea><c:barChart>
                    <c:barDir val="col"/><c:varyColors val="0"/>
                    <c:ser><c:idx val="0"/>{sp_pr}
                      <c:val><c:numCache><c:pt idx="0"><c:v>{value}</c:v></c:pt></c:numCache></c:val>
                    </c:ser>
                  </c:barChart></c:plotArea></c:chart>
                </c:chartSpace>"#
            );
            parse_chart_part(
                chart_space_of(&xml).root_element(),
                &XlsxCompatibilityFixtureResolver,
            )
            .expect("bare column chart parses")
            .series
            .into_iter()
            .next()
            .expect("one series")
        }

        let negative = parsed_series(-24_000, false);
        assert_eq!(negative.invert_if_negative, None);
        assert_eq!(negative.automatic_negative_style, Some(true));
        assert_eq!(negative.inverted_fill_hidden, None);
        assert_eq!(negative.inverted_line_color, None);
        assert_eq!(negative.inverted_line_width_emu, None);

        let positive = parsed_series(24_000, false);
        assert_eq!(positive.invert_if_negative, None);
        assert_eq!(positive.automatic_negative_style, None);
        assert_eq!(positive.inverted_fill_hidden, None);

        let authored = parsed_series(-24_000, true);
        assert_eq!(authored.invert_if_negative, None);
        assert_eq!(authored.automatic_negative_style, None);
        assert_eq!(authored.inverted_fill_hidden, None);

        fn automatic_styles(
            style: &str,
            plot_markup: &str,
            resolver: &dyn ColorResolver,
        ) -> Vec<Option<bool>> {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}" xmlns:c14="http://schemas.microsoft.com/office/drawing/2007/8/2/chart">{style}
                  <c:chart><c:plotArea>{plot_markup}</c:plotArea></c:chart>
                </c:chartSpace>"#
            );
            parse_chart_part(chart_space_of(&xml).root_element(), resolver)
                .expect("scope-boundary chart parses")
                .series
                .into_iter()
                .map(|series| series.automatic_negative_style)
                .collect()
        }
        let negative_series = r#"<c:ser><c:idx val="0"/>
          <c:val><c:numCache><c:pt idx="0"><c:v>-1</c:v></c:pt></c:numCache></c:val>
        </c:ser>"#;
        let observed_plot = format!(
            r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/>{negative_series}</c:barChart>"#
        );

        // Host opt-in is required; the shared DOCX/PPTX default stays unset.
        assert_eq!(
            automatic_styles("", &observed_plot, &FixtureResolver),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(r#"<c:barChart><c:barDir val="col"/>{negative_series}</c:barChart>"#),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:barChart><c:barDir val="col"/><c:varyColors val="1"/>{negative_series}</c:barChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        // Every authored/structural gate outside the observed sign-mirror boundary remains
        // unset until a corresponding Office boundary is available.
        assert_eq!(
            automatic_styles(
                r#"<c:style val="2"/>"#,
                &observed_plot,
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:barChart><c:barDir val="bar"/><c:varyColors val="0"/>{negative_series}</c:barChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:barChart><c:barDir val="col"/><c:grouping val="stacked"/><c:varyColors val="0"/>{negative_series}</c:barChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:bar3DChart><c:barDir val="col"/><c:varyColors val="0"/>{negative_series}</c:bar3DChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/>{negative_series}<c:ser><c:idx val="1"/><c:val><c:numCache><c:pt idx="0"><c:v>-2</c:v></c:pt></c:numCache></c:val></c:ser></c:barChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None, None]
        );
        assert_eq!(
            automatic_styles(
                "",
                r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/><c:ser><c:idx val="0"/><c:dPt><c:idx val="0"/><c:spPr><a:solidFill><a:srgbClr val="00FF00"/></a:solidFill></c:spPr></c:dPt><c:val><c:numCache><c:pt idx="0"><c:v>-1</c:v></c:pt></c:numCache></c:val></c:ser></c:barChart>"#,
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/><c:ser><c:idx val="0"/><c:invertIfNegative val="0"/><c:val><c:numCache><c:pt idx="0"><c:v>-1</c:v></c:pt></c:numCache></c:val></c:ser></c:barChart>"#,
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/><c:ser><c:idx val="0"/><c:val><c:numCache><c:pt idx="0"><c:v>-1</c:v></c:pt></c:numCache></c:val><c:extLst><c:ext uri="invert"><c14:invertSolidFillFmt><c14:spPr><a:solidFill><a:srgbClr val="FF00FF"/></a:solidFill></c14:spPr></c14:invertSolidFillFmt></c:ext></c:extLst></c:ser></c:barChart>"#,
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/><c:ser><c:idx val="0"/><c:val><c:numCache><c:pt idx="0"><c:v>-1</c:v></c:pt><c:pt idx="1"><c:v>1</c:v></c:pt></c:numCache></c:val></c:ser></c:barChart>"#,
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None]
        );
        assert_eq!(
            automatic_styles(
                "",
                &format!(
                    r#"<c:barChart><c:barDir val="col"/><c:varyColors val="0"/>{negative_series}</c:barChart><c:lineChart><c:ser><c:idx val="1"/><c:val><c:numCache><c:pt idx="0"><c:v>-2</c:v></c:pt></c:numCache></c:val></c:ser></c:lineChart>"#
                ),
                &XlsxCompatibilityFixtureResolver,
            ),
            vec![None, None]
        );
    }

    /// (e) `chart_type` normalization for stacked/percentStacked. As of CH13,
    /// `parse_chart_part` routes bar/line/area type detection through the shared
    /// `canonical_chart_type` helper (previously an inline match duplicated the
    /// logic and — as a latent bug — folded a percentStacked BAR down to plain
    /// `stackedBar`, so the renderer's `stackedBarPct` 100%-normalization never
    /// fired for a parsed chart). It now distinguishes the percent variant for
    /// BAR (`stackedBarPct` / `stackedBarHPct`) and AREA (`stackedAreaPct`),
    /// matching the LINE behavior and the standalone helper's own matrix test.
    #[test]
    fn parse_chart_part_stacked_percent_stacked_chart_type() {
        fn bar_chart_type(grouping: &str, bar_dir: &str) -> String {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}"><c:chart><c:plotArea>
                  <c:barChart>
                    <c:barDir val="{bar_dir}"/>
                    <c:grouping val="{grouping}"/>
                    <c:ser><c:idx val="0"/>
                      <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt></c:strCache></c:cat>
                      <c:val><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:val>
                    </c:ser>
                  </c:barChart>
                </c:plotArea></c:chart></c:chartSpace>"#
            );
            let doc = chart_space_of(&xml);
            parse_chart_part(doc.root_element(), &FixtureResolver)
                .unwrap()
                .chart_type
        }
        fn line_chart_type(grouping: &str) -> String {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}"><c:chart><c:plotArea>
                  <c:lineChart>
                    <c:grouping val="{grouping}"/>
                    <c:ser><c:idx val="0"/>
                      <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt></c:strCache></c:cat>
                      <c:val><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt></c:numCache></c:val>
                    </c:ser>
                  </c:lineChart>
                </c:plotArea></c:chart></c:chartSpace>"#
            );
            let doc = chart_space_of(&xml);
            parse_chart_part(doc.root_element(), &FixtureResolver)
                .unwrap()
                .chart_type
        }

        assert_eq!(bar_chart_type("stacked", "col"), "stackedBar");
        // CH13: percentStacked now maps to the Pct canonical variant (the
        // renderer normalizes those to 100%), fixing the prior fold-to-stacked.
        assert_eq!(bar_chart_type("percentStacked", "col"), "stackedBarPct");
        assert_eq!(bar_chart_type("percentStacked", "bar"), "stackedBarHPct");
        // Line + area also distinguish percentStacked.
        assert_eq!(line_chart_type("percentStacked"), "stackedLinePct");
    }

    /// A missing plot area is not a chart. An authored empty chart group is
    /// schema-valid and remains represented so its source-order slot is not
    /// lost when a later group gains data.
    #[test]
    fn parse_chart_part_rejects_missing_plot_area_but_retains_empty_group() {
        let no_plot_area = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}"><c:chart><c:title/></c:chart></c:chartSpace>"#
        );
        assert!(parse_chart_part(
            chart_space_of(&no_plot_area).root_element(),
            &FixtureResolver
        )
        .is_none());

        let empty_series = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}"><c:chart><c:plotArea>
                <c:barChart><c:barDir val="col"/><c:grouping val="clustered"/></c:barChart>
              </c:plotArea></c:chart></c:chartSpace>"#
        );
        let model = parse_chart_part(
            chart_space_of(&empty_series).root_element(),
            &FixtureResolver,
        )
        .expect("empty group remains represented");
        assert!(model.series.is_empty());
        let groups = model.plot_groups.expect("ordered group");
        assert_eq!(groups.len(), 1);
        assert_eq!(
            (groups[0].kind.as_str(), groups[0].series_count),
            ("bar", 0)
        );
    }

    /// §21.2.2.198: a scatter series whose `<c:spPr><a:ln>` is `<a:noFill/>`
    /// has its connecting line turned OFF, overriding the group-level
    /// `<c:scatterStyle val="lineMarker">` (§21.2.2.42). The parser must set
    /// `line_hidden = Some(true)` so the renderer draws markers only. A series with a paintable line leaves
    /// `line_hidden = None`.
    #[test]
    fn parse_chart_part_scatter_series_line_nofill_sets_line_hidden() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:scatterChart>
                  <c:scatterStyle val="lineMarker"/>
                  <c:ser>
                    <c:idx val="0"/>
                    <c:spPr><a:ln w="25400"><a:noFill/></a:ln></c:spPr>
                    <c:xVal><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numCache></c:xVal>
                    <c:yVal><c:numCache><c:pt idx="0"><c:v>10</c:v></c:pt><c:pt idx="1"><c:v>20</c:v></c:pt></c:numCache></c:yVal>
                  </c:ser>
                  <c:ser>
                    <c:idx val="1"/>
                    <c:spPr><a:ln w="19050"><a:solidFill><a:srgbClr val="ED7D31"/></a:solidFill></a:ln></c:spPr>
                    <c:xVal><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numCache></c:xVal>
                    <c:yVal><c:numCache><c:pt idx="0"><c:v>5</c:v></c:pt><c:pt idx="1"><c:v>8</c:v></c:pt></c:numCache></c:yVal>
                  </c:ser>
                  <c:axId val="1"/><c:axId val="2"/>
                </c:scatterChart>
                <c:valAx><c:axId val="1"/><c:axPos val="b"/><c:scaling><c:logBase val="2"/><c:orientation val="maxMin"/></c:scaling><c:majorUnit val="0.5"/><c:minorUnit val="0.1"/><c:crossAx val="2"/></c:valAx>
                <c:valAx><c:axId val="2"/><c:axPos val="l"/><c:scaling><c:logBase val="10"/><c:orientation val="maxMin"/></c:scaling><c:crossAx val="1"/></c:valAx>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let m = parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
            .expect("scatter chart parses");
        assert_eq!(m.chart_type, "scatter");
        assert_eq!(m.scatter_style.as_deref(), Some("lineMarker"));
        assert_eq!(m.cat_axis_major_unit, Some(0.5));
        assert_eq!(m.cat_axis_minor_unit, Some(0.1));
        assert_eq!(m.cat_axis_log_base, Some(2.0));
        assert_eq!(m.cat_axis_orientation.as_deref(), Some("maxMin"));
        assert_eq!(m.val_axis_log_base, Some(10.0));
        assert_eq!(m.val_axis_orientation.as_deref(), Some("maxMin"));
        // Series 0: explicit `<a:noFill/>` line → line_hidden set.
        assert_eq!(
            m.series[0].line_hidden,
            Some(true),
            "a `<a:ln><a:noFill/>` series line must record line_hidden"
        );
        // Series 1: a paintable line → line_hidden stays None (group style governs).
        assert_eq!(
            m.series[1].line_hidden, None,
            "a series with a solid line must NOT set line_hidden"
        );
        assert_eq!(m.series[0].marker_symbol, None);
        assert_eq!(
            m.series[0].automatic_marker_symbol.as_deref(),
            Some("diamond")
        );
        assert_eq!(
            m.series[1].automatic_marker_symbol.as_deref(),
            Some("square")
        );
    }

    /// §21.2.2.47: a per-point `<c:dLbl>` carries its own show-flag group and
    /// text style, overriding the series-level `<c:dLbls>` (§21.2.2.49) for that
    /// point. Office can set `showCatName=0 showPercent=1` plus white text per
    /// slice while the series default is `showCatName=1` black. The parser
    /// must surface both the series default AND the per-point flag / color
    /// overrides, and mark a genuine `<c:delete>` distinctly from a style-only
    /// `<c:dLbl>` (which has an empty `text`).
    #[test]
    fn parse_chart_part_pie_per_point_dlbl_overrides_series_defaults() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart><c:plotArea>
                <c:pieChart>
                  <c:ser>
                    <c:idx val="0"/>
                    <c:dLbls>
                      <c:dLbl>
                        <c:idx val="0"/>
                        <c:txPr><a:p><a:pPr><a:defRPr b="1"><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill></a:defRPr></a:pPr></a:p></c:txPr>
                        <c:showVal val="0"/><c:showCatName val="0"/><c:showSerName val="0"/><c:showPercent val="1"/>
                      </c:dLbl>
                      <c:dLbl>
                        <c:idx val="1"/>
                        <c:delete val="1"/>
                      </c:dLbl>
                      <c:txPr><a:p><a:pPr><a:defRPr b="1"><a:solidFill><a:srgbClr val="000000"/></a:solidFill></a:defRPr></a:pPr></a:p></c:txPr>
                      <c:showVal val="0"/><c:showCatName val="1"/><c:showSerName val="0"/><c:showPercent val="1"/>
                    </c:dLbls>
                    <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt></c:strCache></c:cat>
                    <c:val><c:numCache><c:pt idx="0"><c:v>60</c:v></c:pt><c:pt idx="1"><c:v>40</c:v></c:pt></c:numCache></c:val>
                  </c:ser>
                </c:pieChart>
              </c:plotArea></c:chart>
            </c:chartSpace>"#
        );
        let m = parse_chart_part(chart_space_of(&xml).root_element(), &FixtureResolver)
            .expect("pie chart parses");
        assert_eq!(m.chart_type, "pie");
        let def = m.series[0]
            .series_data_labels
            .as_ref()
            .expect("series-level dLbls present");
        // Series default: category name ON, black text.
        assert!(def.show_cat_name, "series default shows category name");
        assert!(def.show_percent);
        assert_eq!(def.font_color.as_deref(), Some("000000"));

        let ovs = m.series[0]
            .data_label_overrides
            .as_ref()
            .expect("per-point overrides present");
        let ov0 = ovs.iter().find(|o| o.idx == 0).expect("idx 0 override");
        // Per-point idx 0: category name OFF, percent ON, white — overrides the
        // series default so this slice renders as white percent-only.
        assert_eq!(ov0.show_cat_name, Some(false));
        assert_eq!(ov0.show_percent, Some(true));
        assert_eq!(ov0.font_color.as_deref(), Some("FFFFFF"));
        assert_ne!(ov0.deleted, Some(true), "a style-only dLbl is not a delete");

        let ov1 = ovs.iter().find(|o| o.idx == 1).expect("idx 1 override");
        // Per-point idx 1: a genuine `<c:delete>` → flagged so the renderer skips it.
        assert_eq!(ov1.deleted, Some(true));
    }

