    #[test]
    fn linked_chart_style_role_table_counts_referenced_theme_gradients() {
        let roles = CHART_STYLE_ROLE_NAMES
            .iter()
            .map(|name| {
                format!(
                    "<cs:{name}><cs:fillRef idx=\"1\"><cs:styleClr val=\"auto\"/></cs:fillRef></cs:{name}>"
                )
            })
            .collect::<String>();
        let style_xml = format!(
            r#"<cs:chartStyle xmlns:cs="{CS_NS}" xmlns:a="{A_NS}">{roles}</cs:chartStyle>"#,
        );
        let colors = (0..273)
            .map(|index| format!("<a:srgbClr val=\"{:06X}\"/>", index))
            .collect::<String>();
        let colors_xml = format!(
            r#"<cs:colorStyle xmlns:cs="{CS_NS}" xmlns:a="{A_NS}" meth="cycle">{colors}</cs:colorStyle>"#,
        );
        let stops = (0..129)
            .map(|index| {
                format!(
                    "<a:gs pos=\"{}\"><a:schemeClr val=\"phClr\"/></a:gs>",
                    index * 100_000 / 128
                )
            })
            .collect::<String>();
        let theme_xml = format!(
            r#"<a:theme xmlns:a="{A_NS}"><a:themeElements><a:fmtScheme name="bounded"><a:fillStyleLst><a:gradFill><a:gsLst>{stops}</a:gsLst><a:lin ang="0"/></a:gradFill></a:fillStyleLst><a:lnStyleLst/><a:effectStyleLst/><a:bgFillStyleLst/></a:fmtScheme></a:themeElements></a:theme>"#,
        );
        let resolver = FormatSchemeFixtureResolver {
            format_scheme: crate::theme::ThemeFormatScheme::parse(&theme_xml),
        };
        let style_doc = root_of(&style_xml);
        let (_, palette) =
            parse_chart_color_style(&colors_xml, &resolver).expect("color style parses");

        assert!(parse_chart_style_role_table(
            style_doc.root_element(),
            &resolver,
            Some(&palette),
            Some("cycle"),
            &EmptyChartImageResolver,
        )
        .is_none());

        // A local fill choice has higher precedence than fillRef even when the
        // local grammar is not representable. It therefore contributes no
        // inherited gradient work to the aggregate preflight.
        let locally_overridden_roles = CHART_STYLE_ROLE_NAMES
            .iter()
            .map(|name| {
                format!(
                    "<cs:{name}><cs:fillRef idx=\"1\"><cs:styleClr val=\"auto\"/></cs:fillRef><cs:spPr><a:blipFill/></cs:spPr></cs:{name}>"
                )
            })
            .collect::<String>();
        let locally_overridden_style_xml = format!(
            r#"<cs:chartStyle xmlns:cs="{CS_NS}" xmlns:a="{A_NS}">{locally_overridden_roles}</cs:chartStyle>"#,
        );
        let locally_overridden_style_doc = root_of(&locally_overridden_style_xml);
        let table = parse_chart_style_role_table(
            locally_overridden_style_doc.root_element(),
            &resolver,
            Some(&palette),
            Some("cycle"),
            &EmptyChartImageResolver,
        )
        .expect("unsupported local fills suppress inherited gradient work");
        assert!(table
            .values()
            .all(|style| style.fill_paint_authored == Some(true)
                && style.fill_colors.is_none()
                && style.fill_paints.is_none()));
    }

    #[test]
    fn linked_chart_style_role_table_bounds_each_source_paint_recipe() {
        let gradient = |count: usize| {
            (0..count)
                .map(|index| format!(r#"<a:gs pos="{index}"><a:srgbClr val="112233"/></a:gs>"#))
                .collect::<String>()
        };
        let style = |count: usize, outline: bool| {
            let paint = format!(
                r#"<a:gradFill><a:gsLst>{}</a:gsLst><a:lin ang="0"/></a:gradFill>"#,
                gradient(count),
            );
            let sp_pr = if outline {
                format!(r#"<a:noFill/><a:ln>{paint}</a:ln>"#)
            } else {
                paint
            };
            format!(
                r#"<cs:chartStyle xmlns:cs="{CS_NS}" xmlns:a="{A_NS}"><cs:dataPoint3D><cs:spPr>{sp_pr}</cs:spPr></cs:dataPoint3D></cs:chartStyle>"#,
            )
        };

        for outline in [false, true] {
            let exact_xml = style(MAX_CHART_PAINT_RECIPE_COMPONENTS, outline);
            let exact = root_of(&exact_xml);
            assert!(parse_chart_style_role_table(
                exact.root_element(),
                &FixtureResolver,
                None,
                None,
                &EmptyChartImageResolver,
            )
            .is_some());

            let oversized_xml = style(MAX_CHART_PAINT_RECIPE_COMPONENTS + 1, outline);
            let oversized = root_of(&oversized_xml);
            assert!(parse_chart_style_role_table(
                oversized.root_element(),
                &FixtureResolver,
                None,
                None,
                &EmptyChartImageResolver,
            )
            .is_none());
        }
    }

    // ── CH15: chartEx structured layout parsing ──────────────────────────────

    /// A box-and-whisker chart with two series, each referencing its own
    /// `<cx:data>` (via `<cx:dataId>`) of RAW sample points grouped across two
    /// categories. Verifies: (a) categories unique-in-order, (b) each series'
    /// points binned by category, (c) absent explicit series fills preserved,
    /// (d) `<cx:visibility>` / `<cx:statistics>` flags threaded, (e) the title
    /// is parsed and the accent palette exposed.
    #[test]
    fn parse_chartex_part_boxwhisker_two_series_binned_by_category() {
        let xml = format!(
            r#"<cx:chartSpace xmlns:cx="{CX_NS}" xmlns:a="{A_NS}">
              <cx:chartData>
                <cx:data id="0">
                  <cx:strDim type="cat"><cx:lvl ptCount="3">
                    <cx:pt idx="0">Cat A</cx:pt><cx:pt idx="1">Cat A</cx:pt><cx:pt idx="2">Cat B</cx:pt>
                  </cx:lvl></cx:strDim>
                  <cx:numDim type="val"><cx:lvl ptCount="3">
                    <cx:pt idx="0">1</cx:pt><cx:pt idx="1">3</cx:pt><cx:pt idx="2">10</cx:pt>
                  </cx:lvl></cx:numDim>
                </cx:data>
                <cx:data id="1">
                  <cx:strDim type="cat"><cx:lvl ptCount="3">
                    <cx:pt idx="0">Cat A</cx:pt><cx:pt idx="1">Cat B</cx:pt><cx:pt idx="2">Cat B</cx:pt>
                  </cx:lvl></cx:strDim>
                  <cx:numDim type="val"><cx:lvl ptCount="3">
                    <cx:pt idx="0">5</cx:pt><cx:pt idx="1">7</cx:pt><cx:pt idx="2">9</cx:pt>
                  </cx:lvl></cx:numDim>
                </cx:data>
              </cx:chartData>
              <cx:chart>
                <cx:title><cx:tx><cx:rich><a:p><a:r><a:t>My box chart</a:t></a:r></a:p></cx:rich></cx:tx></cx:title>
                <cx:plotArea><cx:plotAreaRegion>
                  <cx:series layoutId="boxWhisker">
                    <cx:tx><cx:txData><cx:v>Series1</cx:v></cx:txData></cx:tx>
                    <cx:dataId val="0"/>
                    <cx:layoutPr>
                      <cx:visibility meanLine="0" meanMarker="1" nonoutliers="0" outliers="1"/>
                      <cx:statistics quartileMethod="exclusive"/>
                    </cx:layoutPr>
                  </cx:series>
                  <cx:series layoutId="boxWhisker">
                    <cx:tx><cx:txData><cx:v>Series2</cx:v></cx:txData></cx:tx>
                    <cx:dataId val="1"/>
                    <cx:layoutPr>
                      <cx:visibility meanLine="1" meanMarker="0" nonoutliers="1" outliers="0"/>
                      <cx:statistics quartileMethod="inclusive"/>
                    </cx:layoutPr>
                  </cx:series>
                </cx:plotAreaRegion></cx:plotArea>
              </cx:chart>
            </cx:chartSpace>"#
        );
        let d = chart_space_of(&xml);
        let m = parse_chartex_part(d.root_element(), &FixtureResolver, None)
            .expect("boxWhisker parses");
        assert_eq!(m.chart_type, "boxWhisker");
        assert_eq!(m.title.as_deref(), Some("My box chart"));
        assert_eq!(
            m.chartex_accents.as_deref(),
            Some(
                &["5B9BD5", "ED7D31", "A5A5A5", "FFC000", "4472C4", "70AD47"].map(String::from)[..]
            )
        );
        let box_data = m.chartex_box.expect("box data present");
        assert_eq!(box_data.categories, vec!["Cat A", "Cat B"]);
        assert_eq!(box_data.series.len(), 2);

        let s0 = &box_data.series[0];
        assert_eq!(s0.name, "Series1");
        assert_eq!(s0.color, None); // shared renderer applies style/theme fallback
                                    // Series1: Cat A got points 1 & 3, Cat B got 10.
        assert_eq!(s0.values_by_category, vec![vec![1.0, 3.0], vec![10.0]]);
        assert!(s0.mean_marker && !s0.mean_line && s0.show_outliers && !s0.show_nonoutliers);
        assert_eq!(s0.quartile_method, "exclusive");

        let s1 = &box_data.series[1];
        assert_eq!(s1.name, "Series2");
        assert_eq!(s1.color, None); // shared renderer applies style/theme fallback
                                    // Series2: Cat A got 5, Cat B got 7 & 9.
        assert_eq!(s1.values_by_category, vec![vec![5.0], vec![7.0, 9.0]]);
        assert!(!s1.mean_marker && s1.mean_line && !s1.show_outliers && s1.show_nonoutliers);
        assert_eq!(s1.quartile_method, "inclusive");
    }

