    /// Full ofPieChart contract retains secondary-plot controls without
    /// disturbing the source-index palette carried by the series.
    #[test]
    fn parse_chart_part_ofpie_full_contract_keeps_split() {
        let ser = r#"<c:ser><c:idx val="0"/>
            <c:cat><c:strCache>
              <c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt>
              <c:pt idx="2"><c:v>C</c:v></c:pt><c:pt idx="3"><c:v>D</c:v></c:pt>
            </c:strCache></c:cat>
            <c:val><c:numCache>
              <c:pt idx="0"><c:v>40</c:v></c:pt><c:pt idx="1"><c:v>30</c:v></c:pt>
              <c:pt idx="2"><c:v>20</c:v></c:pt><c:pt idx="3"><c:v>10</c:v></c:pt>
            </c:numCache></c:val></c:ser>"#;
        // bar-of-pie with a custom split of the last two points into the bar,
        // plus connector series-lines — all of which we ignore.
        let group = format!(
            r#"<c:ofPieChart>
                <c:ofPieType val="bar"/>
                <c:varyColors val="1"/>
                {ser}
                <c:gapWidth val="100"/>
                <c:splitType val="pos"/>
                <c:splitPos val="2"/>
                <c:secondPieSize val="75"/>
                <c:serLines/>
            </c:ofPieChart>"#
        );
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("ofPie parses");
        assert_eq!(m.chart_type, "ofPie");
        assert_eq!(
            m.series[0].values,
            vec![Some(40.0), Some(30.0), Some(20.0), Some(10.0)]
        );
        // varyColors cycled the accent palette across all four slices.
        let colors = m.series[0]
            .data_point_colors
            .as_ref()
            .expect("varyColors slice palette");
        assert_eq!(colors[0].as_deref(), Some("4472C4")); // accent1
        assert_eq!(colors[1].as_deref(), Some("ED7D31")); // accent2
        assert_eq!(colors[2].as_deref(), Some("A5A5A5")); // accent3
        assert_eq!(colors[3].as_deref(), Some("FFC000")); // accent4
        let of_pie = m.of_pie.expect("ofPie contract");
        assert_eq!(of_pie.r#type, "bar");
        assert_eq!(of_pie.split_type, "pos");
        assert!(of_pie.split_type_authored);
        assert_eq!(of_pie.split_pos, Some(2.0));
        assert!(of_pie.split_pos_authored);
        assert_eq!(of_pie.second_pie_size_percent, 75.0);
        assert_eq!(of_pie.gap_width_percent, 100.0);
        assert!(of_pie.series_lines);
    }

    /// A resolver that DOES supply the default series accent palette (like the
    /// real docx/xlsx resolvers), used to pin the §21.2.2.227 `<c:varyColors>`
    /// per-slice accent fill. `FixtureResolver` returns `None` for accents so it
    /// cannot exercise this path.
    struct AccentResolver;
    impl ColorResolver for AccentResolver {
        fn resolve_solid_fill(&self, node: Node) -> Option<String> {
            node.children()
                .find(|n| n.is_element() && n.tag_name().name() == "srgbClr")
                .and_then(|n| attr(&n, "val"))
                .map(|v| v.to_uppercase())
        }
        fn resolve_series_accent(&self, idx: usize) -> Option<String> {
            // Six-accent cycle, matching `theme.accent[(idx % 6) + 1]`.
            const ACCENTS: [&str; 6] = ["4472C4", "ED7D31", "A5A5A5", "FFC000", "5B9BD5", "70AD47"];
            Some(ACCENTS[idx % 6].to_string())
        }
    }

    /// §21.2.2.227 varyColors (default ON for pie): each slice without an
    /// explicit `<c:dPt>` fill takes the theme accent for its point index, so a
    /// docx/xlsx pie matches Office instead of the renderer's built-in palette.
    /// The one slice that DOES carry a `<c:dPt>` fill keeps it.
    #[test]
    fn parse_chart_part_pie_vary_colors_fills_accents() {
        let ser = r#"<c:ser><c:idx val="0"/>
            <c:dPt><c:idx val="0"/><c:spPr><a:solidFill><a:srgbClr val="112233"/></a:solidFill></c:spPr></c:dPt>
            <c:cat><c:strCache>
              <c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt><c:pt idx="2"><c:v>C</c:v></c:pt>
            </c:strCache></c:cat>
            <c:val><c:numCache>
              <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt><c:pt idx="2"><c:v>3</c:v></c:pt>
            </c:numCache></c:val></c:ser>"#;
        // No <c:varyColors> element → defaults to ON for the pie family.
        let group = format!(r#"<c:pieChart>{ser}</c:pieChart>"#);
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("pie parses");
        let colors = m.series[0]
            .data_point_colors
            .as_ref()
            .expect("varyColors populates slice palette");
        assert_eq!(colors[0].as_deref(), Some("112233")); // explicit dPt wins
        assert_eq!(colors[1].as_deref(), Some("ED7D31")); // accent2
        assert_eq!(colors[2].as_deref(), Some("A5A5A5")); // accent3

        // varyColors="0" disables the per-slice accent fill: only the explicit
        // dPt color remains, the rest fall back to None (renderer palette).
        let group_off = format!(r#"<c:pieChart><c:varyColors val="0"/>{ser}</c:pieChart>"#);
        let xml_off = chart_space_with_group(&group_off);
        let d2 = chart_space_of(&xml_off);
        let m2 = parse_chart_part(d2.root_element(), &AccentResolver).expect("pie parses");
        let colors2 = m2.series[0].data_point_colors.as_ref().unwrap();
        assert_eq!(colors2[0].as_deref(), Some("112233"));
        assert_eq!(colors2[1], None);
        assert_eq!(colors2[2], None);
    }

    /// ECMA-376 Part 1 §21.2.3.46, Tables 5-6: legacy Chart Style 2 uses
    /// accent1..accent6 and changes tint/shade when those six colours repeat.
    /// Office distributes completed six-colour sets between -70% and +70%; a
    /// partial trailing set takes the next position without recolouring the
    /// completed sets.  These 13- and 18-point boundaries were measured from
    /// Excel vector output and distinguish that rule from a modulo-six cycle.
    #[test]
    fn parse_chart_part_style2_vary_colors_shades_repeated_accent_sets() {
        let parse = |point_count: usize| {
            let categories = (0..point_count)
                .map(|i| format!(r#"<c:pt idx="{i}"><c:v>P{i}</c:v></c:pt>"#))
                .collect::<String>();
            let values = (0..point_count)
                .map(|i| format!(r#"<c:pt idx="{i}"><c:v>1</c:v></c:pt>"#))
                .collect::<String>();
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
                  <c:style val="2"/><c:chart><c:plotArea><c:pieChart>
                    <c:varyColors val="1"/><c:ser><c:idx val="0"/>
                      <c:cat><c:strLit><c:ptCount val="{point_count}"/>{categories}</c:strLit></c:cat>
                      <c:val><c:numLit><c:ptCount val="{point_count}"/>{values}</c:numLit></c:val>
                    </c:ser>
                  </c:pieChart></c:plotArea></c:chart>
                </c:chartSpace>"#
            );
            let document = chart_space_of(&xml);
            parse_chart_part(document.root_element(), &AccentResolver)
                .expect("style 2 pie parses")
                .series
                .remove(0)
                .data_point_colors
                .expect("style 2 varyColors palette")
        };

        let thirteen = parse(13);
        assert_eq!(thirteen[0].as_deref(), Some("375DA1"));
        assert_eq!(thirteen[6].as_deref(), Some("4472C4"));
        assert_eq!(thirteen[12].as_deref(), Some("A7B5DB"));

        let eighteen = parse(18);
        assert_eq!(eighteen[0].as_deref(), Some("335899"));
        assert_eq!(eighteen[6].as_deref(), Some("3F6AB7"));
        assert_eq!(eighteen[12].as_deref(), Some("7991CE"));
    }

    /// A SINGLE-series bar chart with `<c:varyColors>` ABSENT varies by point by
    /// default (issue #931): each data point takes the accent for its index and
    /// the chart-level flag is set. Office-produced lone column series rotate
    /// through the theme palette even without a `<c:varyColors>` element.
    #[test]
    fn parse_chart_part_bar_single_series_varies_by_default() {
        let group = format!(
            r#"<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>{CH13_SER}</c:barChart>"#
        );
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("bar parses");
        assert_eq!(m.vary_colors, Some(true));
        let colors = m.series[0]
            .data_point_colors
            .as_ref()
            .expect("default vary populates per-point palette");
        assert_eq!(colors[0].as_deref(), Some("4472C4")); // accent1
        assert_eq!(colors[1].as_deref(), Some("ED7D31")); // accent2
    }

    /// A SINGLE-series bar chart with an explicit `<c:varyColors val="0"/>`
    /// keeps its one per-series color (Office records the forced-single-color
    /// choice this way). No per-point fill,
    /// no chart-level flag.
    #[test]
    fn parse_chart_part_bar_single_series_vary_off_keeps_series_color() {
        let group = format!(
            r#"<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="0"/>{CH13_SER}</c:barChart>"#
        );
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("bar parses");
        assert_eq!(m.vary_colors, None);
        assert!(m.series[0].data_point_colors.is_none());
    }

    /// §21.2.2.227 varyColors on a SINGLE-series bar/column chart: each data
    /// point (bar) without an explicit `<c:dPt>` fill takes the theme accent for
    /// its point index, and the chart-level `vary_colors` flag is set so the
    /// core renderer colors each bar per point and lists one legend entry per
    /// point (issue #931). The point that carries a `<c:dPt>` fill keeps it.
    #[test]
    fn parse_chart_part_bar_vary_colors_single_series_fills_accents() {
        let ser = r#"<c:ser><c:idx val="0"/>
            <c:dPt><c:idx val="0"/><c:spPr><a:solidFill><a:srgbClr val="112233"/></a:solidFill></c:spPr></c:dPt>
            <c:cat><c:strCache>
              <c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt>
              <c:pt idx="2"><c:v>C</c:v></c:pt><c:pt idx="3"><c:v>D</c:v></c:pt>
            </c:strCache></c:cat>
            <c:val><c:numCache>
              <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt>
              <c:pt idx="2"><c:v>3</c:v></c:pt><c:pt idx="3"><c:v>4</c:v></c:pt>
            </c:numCache></c:val></c:ser>"#;
        let group = format!(
            r#"<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="1"/>{ser}</c:barChart>"#
        );
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("bar parses");
        assert_eq!(m.vary_colors, Some(true));
        let colors = m.series[0]
            .data_point_colors
            .as_ref()
            .expect("varyColors populates per-point palette");
        assert_eq!(colors[0].as_deref(), Some("112233")); // explicit dPt wins
        assert_eq!(colors[1].as_deref(), Some("ED7D31")); // accent2
        assert_eq!(colors[2].as_deref(), Some("A5A5A5")); // accent3
        assert_eq!(colors[3].as_deref(), Some("FFC000")); // accent4
    }

    /// §21.2.2.227 varyColors on a MULTI-series bar chart is a no-op for the
    /// per-point fill: Office keeps per-series colors when several series share
    /// the axes, so neither the per-point palette nor the chart-level flag is
    /// emitted. Only the single-series case (issue #931) varies by point.
    #[test]
    fn parse_chart_part_bar_vary_colors_multi_series_keeps_series_colors() {
        let ser0 = r#"<c:ser><c:idx val="0"/>
            <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt></c:strCache></c:cat>
            <c:val><c:numCache><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numCache></c:val></c:ser>"#;
        let ser1 = r#"<c:ser><c:idx val="1"/>
            <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt></c:strCache></c:cat>
            <c:val><c:numCache><c:pt idx="0"><c:v>3</c:v></c:pt><c:pt idx="1"><c:v>4</c:v></c:pt></c:numCache></c:val></c:ser>"#;
        let group = format!(
            r#"<c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="1"/>{ser0}{ser1}</c:barChart>"#
        );
        let xml = chart_space_with_group(&group);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &AccentResolver).expect("bar parses");
        assert_eq!(m.vary_colors, None);
        assert!(m.series[0].data_point_colors.is_none());
        assert!(m.series[1].data_point_colors.is_none());
    }

    /// A named single series in `<c:tx>` — reused by the auto-title tests. `idx`
    /// distinguishes the two series in the multi-series fixture.
    fn named_ser(idx: u32, name: &str) -> String {
        format!(
            r#"<c:ser><c:idx val="{idx}"/>
              <c:tx><c:strRef><c:strCache><c:pt idx="0"><c:v>{name}</c:v></c:pt></c:strCache></c:strRef></c:tx>
              <c:cat><c:strCache><c:pt idx="0"><c:v>A</c:v></c:pt></c:strCache></c:cat>
              <c:val><c:numCache><c:pt idx="0"><c:v>3</c:v></c:pt></c:numCache></c:val>
            </c:ser>"#
        )
    }

    /// A `<c:chart>` with an optional `<c:autoTitleDeleted val=…>`, NO explicit
    /// `<c:title>` text, and the given series in a bar plot area. Models the
    /// observed auto-title shape: title frame present but empty, so the
    /// synthesized title comes from the sole series name.
    fn chart_space_auto_title(auto_title_deleted: Option<&str>, sers: &str) -> String {
        let atd = auto_title_deleted
            .map(|v| format!(r#"<c:autoTitleDeleted val="{v}"/>"#))
            .unwrap_or_default();
        format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:chart>
                {atd}
                <c:plotArea>
                  <c:barChart><c:barDir val="col"/><c:grouping val="clustered"/>{sers}</c:barChart>
                  <c:catAx><c:axId val="1"/><c:axPos val="b"/></c:catAx>
                  <c:valAx><c:axId val="2"/><c:axPos val="l"/></c:valAx>
                </c:plotArea>
              </c:chart>
            </c:chartSpace>"#
        )
    }

    /// ECMA-376 §21.2.2.7 auto-title: a chart with NO explicit title text,
    /// `autoTitleDeleted` absent (⇒ auto title may show), and EXACTLY ONE named
    /// series adopts that series' name as the chart title. Word-produced output
    /// with a lone named series and an empty title frame provides the
    /// compatibility evidence.
    #[test]
    fn parse_chart_part_auto_title_single_series() {
        let xml = chart_space_auto_title(None, &named_ser(0, "Production in 2017"));
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &FixtureResolver).expect("parses");
        // The series name is promoted VERBATIM (the `cap="all"` uppercase is a
        // rendering-layer transform we do not apply at parse time).
        assert_eq!(m.title.as_deref(), Some("Production in 2017"));

        // An explicit `autoTitleDeleted val="0"` behaves identically (0 ⇒ auto
        // title may be shown).
        let xml0 = chart_space_auto_title(Some("0"), &named_ser(0, "Production in 2017"));
        let d0 = chart_space_of(&xml0);
        let m0 = parse_chart_part(d0.root_element(), &FixtureResolver).expect("parses");
        assert_eq!(m0.title.as_deref(), Some("Production in 2017"));
    }

    /// §21.2.2.7 `autoTitleDeleted val="1"` (or `"true"`) suppresses the auto
    /// title even for a single named series — Word shows no title.
    #[test]
    fn parse_chart_part_auto_title_deleted_shows_no_title() {
        for v in ["1", "true"] {
            let xml = chart_space_auto_title(Some(v), &named_ser(0, "Production in 2017"));
            let d = chart_space_of(&xml);
            let m = parse_chart_part(d.root_element(), &FixtureResolver).expect("parses");
            assert_eq!(m.title, None, "autoTitleDeleted={v} should suppress title");
        }
    }

    /// §21.2.2.7 auto-title applies ONLY to single-series charts. With TWO
    /// series, Word shows no synthesized title (a lone series name would be
    /// misleading), so `title` stays `None`.
    #[test]
    fn parse_chart_part_auto_title_multi_series_none() {
        let sers = format!(
            "{}{}",
            named_ser(0, "Series One"),
            named_ser(1, "Series Two")
        );
        let xml = chart_space_auto_title(None, &sers);
        let d = chart_space_of(&xml);
        let m = parse_chart_part(d.root_element(), &FixtureResolver).expect("parses");
        assert_eq!(m.series.len(), 2);
        assert_eq!(m.title, None);
    }

    struct FormulaResolver;

    impl ChartReferenceResolver for FormulaResolver {
        fn resolve_strings(&mut self, formula: &str) -> Option<Vec<String>> {
            Some(match formula {
                "Name" => vec!["Resolved series".into()],
                "X" => vec!["1".into(), "2".into()],
                "CachedCats" => vec!["live value must not win".into()],
                _ => return None,
            })
        }

        fn resolve_numbers(&mut self, formula: &str) -> Option<Vec<Option<f64>>> {
            Some(match formula {
                "Y" => vec![Some(10.0), Some(20.0)],
                "Size" => vec![Some(3.0), Some(5.0)],
                _ => return None,
            })
        }
    }

    #[test]
    fn parse_chart_part_resolves_cacheless_bubble_fields() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}"><c:chart><c:plotArea><c:bubbleChart>
              <c:ser><c:idx val="0"/><c:order val="0"/>
                <c:tx><c:strRef><c:f>Name</c:f></c:strRef></c:tx>
                <c:xVal><c:numRef><c:f>X</c:f></c:numRef></c:xVal>
                <c:yVal><c:numRef><c:f>Y</c:f></c:numRef></c:yVal>
                <c:bubbleSize><c:numRef><c:f>Size</c:f></c:numRef></c:bubbleSize>
              </c:ser>
              <c:bubbleScale val="40"/>
              <c:sizeRepresents val="w"/>
              <c:showNegBubbles/>
            </c:bubbleChart></c:plotArea></c:chart></c:chartSpace>"#
        );
        let doc = root_of(&xml);
        let mut references = FormulaResolver;
        let chart =
            parse_chart_part_with_references(doc.root_element(), &FixtureResolver, &mut references)
                .expect("bubble chart parses");

        assert_eq!(chart.categories, vec!["1", "2"]);
        assert_eq!(chart.series[0].name, "Resolved series");
        assert_eq!(chart.series[0].categories, None);
        assert_eq!(chart.series[0].values, vec![Some(10.0), Some(20.0)]);
        assert_eq!(
            chart.series[0].bubble_sizes,
            Some(vec![Some(3.0), Some(5.0)])
        );
        assert_eq!(chart.bubble_scale, Some(40));
        assert_eq!(chart.bubble_size_represents.as_deref(), Some("w"));
        assert_eq!(chart.show_negative_bubbles, Some(true));

        // Strict OOXML uses the percentage lexical form; Transitional accepts
        // both this and the integer form above.
        let strict_xml = xml.replace(
            "<c:bubbleScale val=\"40\"/>",
            "<c:bubbleScale val=\"40%\"/>",
        );
        let strict_doc = root_of(&strict_xml);
        let mut strict_references = FormulaResolver;
        let strict_chart = parse_chart_part_with_references(
            strict_doc.root_element(),
            &FixtureResolver,
            &mut strict_references,
        )
        .expect("strict bubble scale parses");
        assert_eq!(strict_chart.bubble_scale, Some(40));

        let disabled_xml = xml.replace("<c:showNegBubbles/>", "<c:showNegBubbles val=\"false\"/>");
        let disabled_doc = root_of(&disabled_xml);
        let mut disabled_references = FormulaResolver;
        let disabled_chart = parse_chart_part_with_references(
            disabled_doc.root_element(),
            &FixtureResolver,
            &mut disabled_references,
        )
        .expect("explicit false showNegBubbles parses");
        assert_eq!(disabled_chart.show_negative_bubbles, Some(false));
    }

    #[test]
    fn parse_chart_part_preserves_bubble3d_group_series_and_point_provenance() {
        for namespace in [C_NS, "http://purl.oclc.org/ooxml/drawingml/chart"] {
            let xml = format!(
                r#"<c:chartSpace xmlns:c="{namespace}"><c:chart><c:plotArea>
                  <c:bubbleChart>
                    <c:ser><c:idx val="0"/><c:order val="0"/>
                      <c:dPt><c:idx val="0"/><c:bubble3D/></c:dPt>
                      <c:xVal><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numLit></c:xVal>
                      <c:yVal><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>3</c:v></c:pt><c:pt idx="1"><c:v>4</c:v></c:pt></c:numLit></c:yVal>
                      <c:bubbleSize><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>5</c:v></c:pt><c:pt idx="1"><c:v>6</c:v></c:pt></c:numLit></c:bubbleSize>
                      <c:bubble3D val="0"/>
                    </c:ser>
                    <c:bubble3D/>
                    <c:axId val="1"/><c:axId val="2"/>
                  </c:bubbleChart>
                  <c:bubbleChart>
                    <c:ser><c:idx val="1"/><c:order val="1"/>
                      <c:dPt><c:idx val="0"/><c:bubble3D/></c:dPt>
                      <c:dPt><c:idx val="1"/><c:bubble3D val="TRUE"/></c:dPt>
                      <c:xVal><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt></c:numLit></c:xVal>
                      <c:yVal><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>7</c:v></c:pt><c:pt idx="1"><c:v>8</c:v></c:pt></c:numLit></c:yVal>
                      <c:bubbleSize><c:numLit><c:ptCount val="2"/><c:pt idx="0"><c:v>5</c:v></c:pt><c:pt idx="1"><c:v>6</c:v></c:pt></c:numLit></c:bubbleSize>
                    </c:ser>
                    <c:bubble3D val="false"/>
                    <c:axId val="1"/><c:axId val="2"/>
                  </c:bubbleChart>
                </c:plotArea></c:chart></c:chartSpace>"#
            );
            let document = root_of(&xml);
            let chart = parse_chart_part(document.root_element(), &FixtureResolver)
                .expect("bubble chart parses");

            assert_eq!(chart.series.len(), 2);
            assert_eq!(chart.series[0].bubble_3d_group_default, Some(true));
            assert_eq!(chart.series[0].bubble_3d, Some(false));
            let first_points = chart.series[0]
                .data_point_overrides
                .as_ref()
                .expect("bubble3D-only point is retained");
            assert_eq!(first_points.len(), 1);
            assert_eq!(first_points[0].bubble_3d, Some(true));

            assert_eq!(chart.series[1].bubble_3d_group_default, Some(false));
            assert_eq!(chart.series[1].bubble_3d, None);
            let second_points = chart.series[1]
                .data_point_overrides
                .as_ref()
                .expect("both point booleans are retained");
            assert_eq!(second_points.len(), 2);
            assert_eq!(second_points[0].bubble_3d, Some(true));
            assert_eq!(
                second_points[1].bubble_3d,
                Some(false),
                "invalid xsd:boolean stays authored and fails closed"
            );

            let wire = serde_json::to_value(&chart).expect("chart serializes");
            assert_eq!(wire["series"][0]["bubble3DGroupDefault"], true);
            assert_eq!(wire["series"][0]["bubble3D"], false);
            assert_eq!(
                wire["series"][0]["dataPointOverrides"][0]["bubble3D"], true,
                "the Rust-to-TypeScript boundary preserves DrawingML's 3D token"
            );
            assert!(wire["series"][0].get("bubble3d").is_none());
            assert!(wire["series"][0]["dataPointOverrides"][0]
                .get("bubble3d")
                .is_none());
        }
    }

    #[test]
    fn parse_chart_part_ignores_legacy_series_bubble3d_outside_bubble_family() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea><c:lineChart>
              <c:ser><c:idx val="0"/><c:order val="0"/>
                <c:dPt><c:idx val="0"/><c:spPr><a:gradFill><a:gsLst>
                  <a:gs pos="0"><a:srgbClr val="112233"/></a:gs>
                  <a:gs pos="100000"><a:srgbClr val="DDEEFF"/></a:gs>
                </a:gsLst></a:gradFill></c:spPr><c:bubble3D/></c:dPt>
                <c:cat><c:strLit><c:ptCount val="1"/><c:pt idx="0"><c:v>A</c:v></c:pt></c:strLit></c:cat>
                <c:val><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val>
                <c:bubble3D/>
              </c:ser>
            </c:lineChart></c:plotArea></c:chart></c:chartSpace>"#
        );
        let document = root_of(&xml);
        let chart =
            parse_chart_part(document.root_element(), &FixtureResolver).expect("line chart parses");
        assert_eq!(chart.series[0].bubble_3d_group_default, None);
        assert_eq!(chart.series[0].bubble_3d, None);
        let point = &chart.series[0].data_point_overrides.as_ref().unwrap()[0];
        assert_eq!(
            point.bubble_3d,
            Some(true),
            "CT_DPt is shared and retains the point value without applying it to lines"
        );
        assert_eq!(
            point.chartex_style, None,
            "non-bubble dPt keeps the legacy model"
        );
    }

    #[test]
    fn parse_chart_part_keeps_bounded_bubble_point_structured_fill() {
        let xml = format!(
            r#"<c:chartSpace xmlns:c="{C_NS}" xmlns:a="{A_NS}"><c:chart><c:plotArea>
              <c:bubbleChart><c:ser><c:idx val="0"/><c:order val="0"/>
                <c:dPt><c:idx val="0"/><c:spPr><a:gradFill><a:gsLst>
                  <a:gs pos="0"><a:srgbClr val="112233"/></a:gs>
                  <a:gs pos="100000"><a:srgbClr val="DDEEFF"/></a:gs>
                </a:gsLst></a:gradFill></c:spPr></c:dPt>
                <c:xVal><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:xVal>
                <c:yVal><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>2</c:v></c:pt></c:numLit></c:yVal>
                <c:bubbleSize><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>3</c:v></c:pt></c:numLit></c:bubbleSize>
              </c:ser></c:bubbleChart>
            </c:plotArea></c:chart></c:chartSpace>"#
        );
        let document = root_of(&xml);
        let chart = parse_chart_part(document.root_element(), &FixtureResolver)
            .expect("bubble chart parses");
        let point = &chart.series[0].data_point_overrides.as_ref().unwrap()[0];
        let style = point
            .chartex_style
            .as_ref()
            .expect("bubble dPt keeps shape paint");
        assert_eq!(style.fill_paint_authored, Some(true));
        assert!(matches!(
            style.fill_paints.as_deref(),
            Some([Some(ChartStyleFill::Gradient { stops, .. })]) if stops.len() == 2
        ));
    }

    #[test]
    fn bubble_point_shape_paints_share_the_marker_aggregate_budget() {
        let xml = format!(
            r#"<c:ser xmlns:c="{C_NS}" xmlns:a="{A_NS}">
              <c:dPt><c:idx val="0"/><c:spPr><a:pattFill prst="pct20">
                <a:fgClr><a:srgbClr val="112233"/></a:fgClr>
                <a:bgClr><a:srgbClr val="DDEEFF"/></a:bgClr>
              </a:pattFill></c:spPr></c:dPt>
              <c:dPt><c:idx val="1"/><c:spPr><a:ln><a:pattFill prst="pct30">
                <a:fgClr><a:srgbClr val="445566"/></a:fgClr>
                <a:bgClr><a:srgbClr val="AABBCC"/></a:bgClr>
              </a:pattFill></a:ln></c:spPr></c:dPt>
            </c:ser>"#
        );
        let document = root_of(&xml);
        let mut component_budget = 1;
        let mut paint_budget_exceeded = false;
        let _ = parse_data_point_overrides_with_budget(
            document.root_element(),
            &FixtureResolver,
            &EmptyChartImageResolver,
            true,
            &mut component_budget,
            &mut paint_budget_exceeded,
        );
        assert!(paint_budget_exceeded);
        assert_eq!(component_budget, 0);
    }

    /// Office varies a lone bubble series by point when `<c:varyColors>` is
    /// omitted, just as it does for a lone bar series.  An authored false value
    /// remains authoritative and keeps the series fill for every bubble.
    #[test]
    fn parse_chart_part_bubble_vary_colors_defaults_on_and_honors_false() {
        let ser = r#"<c:ser><c:idx val="0"/><c:order val="0"/>
            <c:xVal><c:numLit><c:ptCount val="3"/>
              <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt><c:pt idx="2"><c:v>3</c:v></c:pt>
            </c:numLit></c:xVal>
            <c:yVal><c:numLit><c:ptCount val="3"/>
              <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt><c:pt idx="2"><c:v>3</c:v></c:pt>
            </c:numLit></c:yVal>
            <c:bubbleSize><c:numLit><c:ptCount val="3"/>
              <c:pt idx="0"><c:v>100</c:v></c:pt><c:pt idx="1"><c:v>400</c:v></c:pt><c:pt idx="2"><c:v>900</c:v></c:pt>
            </c:numLit></c:bubbleSize>
          </c:ser>"#;
        let default_xml = chart_space_with_group(&format!("<c:bubbleChart>{ser}</c:bubbleChart>"));
        let default_doc = chart_space_of(&default_xml);
        let default_chart = parse_chart_part(default_doc.root_element(), &AccentResolver)
            .expect("bubble chart parses");
        let colors = default_chart.series[0]
            .data_point_colors
            .as_ref()
            .expect("default point palette");
        assert_eq!(colors[0].as_deref(), Some("4472C4"));
        assert_eq!(colors[1].as_deref(), Some("ED7D31"));
        assert_eq!(colors[2].as_deref(), Some("A5A5A5"));

        let off_xml = chart_space_with_group(&format!(
            "<c:bubbleChart><c:varyColors val=\"0\"/>{ser}</c:bubbleChart>"
        ));
        let off_doc = chart_space_of(&off_xml);
        let off_chart =
            parse_chart_part(off_doc.root_element(), &AccentResolver).expect("bubble chart parses");
        assert!(off_chart.series[0].data_point_colors.is_none());

        let point_formats = r#"<c:dPt><c:idx val="1"/><c:spPr><a:solidFill><a:srgbClr val="FF0000"/></a:solidFill></c:spPr></c:dPt>
            <c:dPt><c:idx val="2"/><c:spPr><a:noFill/></c:spPr></c:dPt>"#;
        let no_fill_ser = ser.replace(
            "<c:xVal>",
            &format!(r#"<c:spPr><a:noFill/></c:spPr>{point_formats}<c:xVal>"#),
        );
        let no_fill_xml = chart_space_with_group(&format!(
            "<c:bubbleChart><c:varyColors/>{no_fill_ser}</c:bubbleChart>"
        ));
        let no_fill_doc = chart_space_of(&no_fill_xml);
        let no_fill_chart = parse_chart_part(no_fill_doc.root_element(), &AccentResolver)
            .expect("noFill bubble parses");
        assert_eq!(no_fill_chart.series[0].color.as_deref(), Some("00000000"));
        assert_eq!(
            no_fill_chart.series[0].data_point_colors,
            Some(vec![
                None,
                Some("FF0000".to_string()),
                Some("00000000".to_string())
            ]),
        );

        let solid_ser = ser.replace(
            "<c:xVal>",
            &format!(r#"<c:spPr><a:solidFill><a:srgbClr val="00FF00"/></a:solidFill></c:spPr>{point_formats}<c:xVal>"#),
        );
        let solid_xml = chart_space_with_group(&format!(
            "<c:bubbleChart><c:varyColors/>{solid_ser}</c:bubbleChart>"
        ));
        let solid_doc = chart_space_of(&solid_xml);
        let solid_chart = parse_chart_part(solid_doc.root_element(), &AccentResolver)
            .expect("solid bubble parses");
        assert_eq!(
            solid_chart.series[0].data_point_colors,
            Some(vec![
                Some("4472C4".to_string()),
                Some("FF0000".to_string()),
                Some("00000000".to_string()),
            ]),
        );
    }

